import{n}from"./shared-CAKwAg2C.js";const t={"LEARN HOW THE INTERNET WORKS":"PELAJARI CARA KERJA INTERNET","NOW LEARNING":"SEDANG DIPELAJARI","OSI LAYER":"LAPISAN OSI","LEARNING PROGRESS":"KEMAJUAN ANDA",COMPLETE:"SELESAI","IN PROGRESS":"BERJALAN","{pct}% complete":"{pct}% selesai","DESIGNED BY":"DIRANCANG OLEH","Dilum Sanjaya on X":"Dilum Sanjaya di X","Layer {n}: {name}":"Lapisan {n}: {name}",Physical:"Fisik","Data Link":"Tautan data",Network:"Jaringan",Transport:"Transport",Session:"Sesi",Presentation:"Presentasi",Application:"Aplikasi","OVERVIEW · {n} STEPS":"IKHTISAR · {n} LANGKAH","STEP {n}/{total} · {title}":"LANGKAH {n}/{total} · {title}","LESSON COMPLETE":"PELAJARAN SELESAI",PROTOCOLS:"PROTOKOL",Protocols:"Protokol",Language:"Bahasa",Theme:"Tema","Light mode":"Mode terang","Dark mode":"Mode gelap","INTERNET PROTOCOLS":"PROTOKOL INTERNET",More:"Lainnya","Close the protocol list":"Tutup daftar protokol","Close (Esc)":"Tutup (Esc)",ALL:"SEMUA",CORE:"INTI",APPLICATION:"APLIKASI",SECURITY:"KEAMANAN",NETWORK:"JARINGAN",SEQUENCE:"URUTAN",View:"Tampilan","Switch view (V)":"Ganti tampilan (V)","Network diagram":"Diagram jaringan","Sequence diagram":"Diagram urutan","STEP {n}":"LANGKAH {n}","PROTOCOL OVERVIEW":"IKHTISAR","STEP DETAILS":"DETAIL LANGKAH","LESSON SUMMARY":"RINGKASAN",OVERVIEW:"AWAL",ACTIVE:"AKTIF","STEP {n} OF {total}":"LANGKAH {n} DARI {total}","PACKET {n} OF {total}":"PAKET {n} DARI {total}","PACKETS {from}–{to} OF {total}":"PAKET {from}–{to} DARI {total}","{n} LOST":"{n} HILANG","1 LOST":"1 HILANG",ENCRYPTED:"TERENKRIPSI","LOST ON THE WAY":"HILANG DI JALAN","PACKET FLOW":"ALIRAN PAKET","Colour key":"Keterangan warna","Playback speed":"Kecepatan putar","Previous step (←)":"Langkah sebelumnya (←)","Previous step":"Langkah sebelumnya","Play / pause (Space)":"Putar / jeda (Spasi)",PLAY:"PUTAR",PAUSE:"JEDA",REPLAY:"ULANGI",STEP:"LANGKAH","One packet at a time":"Satu paket setiap kali",RESET:"ATUR ULANG",Reset:"Atur ulang","Back to the overview (Esc)":"Kembali ke ikhtisar (Esc)","NO.":"NO.",TIME:"WAKTU",SOURCE:"SUMBER",DESTINATION:"TUJUAN",PROTOCOL:"PROTOKOL",INFO:"INFO",SIZE:"UKURAN","No packets on the wire yet.":"Belum ada paket di jaringan.",LOST:"HILANG","Packet inspector":"Pemeriksa paket","Previous packet":"Paket sebelumnya","Previous packet (←)":"Paket sebelumnya (←)","Next packet":"Paket berikutnya","Next packet (→)":"Paket berikutnya (→)",Close:"Tutup","E.G.":"MIS.","an example value: it differs in every real capture":"nilai contoh: berbeda di setiap tangkapan nyata","bytes the lesson can’t show: encrypted, random, or a file’s contents":"byte yang tidak bisa ditampilkan pelajaran: terenkripsi, acak, atau isi sebuah berkas",BYTES:"BYTE","{n} in this frame":"{n} di frame ini","This row stands for {n} TCP segments carrying a {size}-byte message; the first segment is shown":"Baris ini mewakili {n} segmen TCP yang membawa pesan {size} byte; yang ditampilkan adalah segmen pertama","This packet was lost on the way":"Paket ini hilang di jalan",Padding:"Padding","192.168.1.10/24 · 24 H LEASE":"192.168.1.10/24 · SEWA 24 JAM","2 SEGMENTS":"2 SEGMEN","3 SEGMENTS":"3 SEGMEN","3 DATAGRAMS":"3 DATAGRAM","4 DATAGRAMS":"4 DATAGRAM","203.0.113.10 IS NOT LOCAL":"203.0.113.10 BUKAN LOKAL","250 QUEUED":"250 DIANTREKAN",ANSWER:"JAWABAN","APP COVERS THE 20 MS GAP":"APLIKASI MENUTUP CELAH 20 MS","APP DATA":"DATA APLIKASI","ARP REPLY":"BALASAN ARP","ARP REQUEST":"PERMINTAAN ARP","ARRIVED WITH TTL 116":"TIBA DENGAN TTL 116","AUTH FAILURE":"AUTH GAGAL","At QUIT":"Saat QUIT","CACHED · TTL 3600 S":"DI CACHE · TTL 3600 S","CERTIFICATE VALID":"SERTIFIKAT SAH","CHAIN LEADS TO A TRUSTED ROOT":"RANTAI BERUJUNG DI ROOT TEPERCAYA","CHANNEL OPEN":"BUKA KANAL",CONFIRMED:"DIKONFIRMASI","DNS QUERY":"KUERI DNS","DNS REPLY":"BALASAN DNS","DUP ACK":"ACK GANDA","EACH KEY IS ITS OWN PACKET":"TIAP TOMBOL SATU PAKET",ECHO:"ECHO","ECHO REPLY":"BALASAN ECHO","ECHO REQUEST":"PERMINTAAN ECHO",ENTER:"ENTER","FRAME 7 LOST · NOT RESENT":"FRAME 7 HILANG · TIDAK DIKIRIM ULANG","HOP 2 · 198.51.100.1":"HOP 2 · 198.51.100.1","HOST KEY MATCHES KNOWN_HOSTS":"KUNCI HOST COCOK DENGAN KNOWN_HOSTS","IN BOB’S MAILBOX":"DI KOTAK SURAT BOB","IP PACKET":"PAKET IP",MESSAGE:"PESAN","MESSAGE 1 DELETED":"PESAN 1 DIHAPUS","NEW MAIL ARRIVED":"SURAT BARU TIBA","NO IP ADDRESS YET":"BELUM ADA ALAMAT IP","NOT IN CACHE":"TIDAK ADA DI CACHE","OFFER KEY":"TAWARKAN KUNCI",OUTPUT:"KELUARAN","PASSWORD IN PLAIN TEXT":"KATA SANDI TEKS POLOS",REFERRAL:"RUJUKAN",REPLY:"BALASAN",RESEND:"KIRIM ULANG","SEGMENT 1 LOST":"SEGMEN 1 HILANG","SFTP or FTPS":"SFTP atau FTPS","SFTP, or FTPS (FTP + TLS)":"SFTP, atau FTPS (FTP + TLS)","SHARED SECRET COMPUTED":"RAHASIA BERSAMA DIHITUNG",SIGNED:"DITANDATANGANI","STILL ON SERVER · \\SEEN":"MASIH DI SERVER · \\SEEN",SUCCESS:"BERHASIL","TIME EXCEEDED":"WAKTU HABIS","TIME=34MS TTL=52":"WAKTU=34MS TTL=52",UNREACHABLE:"TAK TERJANGKAU",VERSION:"VERSI","VOICE 1":"SUARA 1","+OK or -ERR":"+OK atau -ERR",".com Server":"Server .com",Authoritative:"Otoritatif","Log In":"Masuk",Key:"Kunci",Why:"Mengapa",End:"Akhir","MACs, in":"MAC, masuk",Internet:"Internet",Router:"Router","Router 192.168.1.1":"Router 192.168.1.1","Router: 192.168.1.1":"Router: 192.168.1.1",Routers:"Router",Hardware:"Perangkat keras",Audio:"Audio",Ping:"Ping",Cookie:"Cookie","Magic cookie":"Magic cookie",Visible:"Terlihat",Tickets:"Tiket","4, 20 bytes":"4, 20 byte","20–60 bytes":"20–60 byte","20–60 bytes (IPv4)":"20–60 byte (IPv4)","8 bytes (TCP: 20+)":"8 byte (TCP: 20+)","32 bytes (Windows)":"32 byte (Windows)","1,460 bytes (MSS)":"1,460 byte (MSS)","78 bytes (seq 1–78)":"78 byte (seq 1–78)","bytes 1461–2920":"byte 1461–2920","text/html, 12.2 KB":"text/html, 12.2 KB","1026 (× 256 = 262,656 bytes)":"1026 (× 256 = 262,656 byte)","501 (× 128 = 64,128 bytes)":"501 (× 128 = 64,128 byte)","X25519MLKEM768 (1,216 bytes), X25519":"X25519MLKEM768 (1,216 byte), X25519","X25519MLKEM768 (1,120 bytes)":"X25519MLKEM768 (1,120 byte)",'"abcdefghijklmnopqrstuvwabcdefghi" (32 bytes)':'"abcdefghijklmnopqrstuvwabcdefghi" (32 byte)','"hello, anyone here" (18 bytes)':'"hello, anyone here" (18 byte)',"32 bits (IPv4), 128 (IPv6)":"32 bit (IPv4), 128 (IPv6)","64 → 52 (12 routers)":"64 → 52 (12 router)","52 (64 − 12 routers)":"52 (64 − 12 router)","1 (Ethernet)":"1 (Ethernet)","report.pdf, 4,000 bytes":"report.pdf, 4,000 byte","1190 bytes (sntrup761 1,158 + X25519 32)":"1190 byte (sntrup761 1,158 + X25519 32)","RTP + audio":"RTP + audio"},i={"Hypertext Transfer Protocol":"Transfer hiperteks","HTTP Secure":"HTTP aman","Transmission Control Protocol":"Protokol kontrol transmisi","User Datagram Protocol":"Protokol datagram pengguna","Internet Protocol":"Protokol internet","Domain Name System":"Sistem nama domain","Dynamic Host Configuration":"Konfigurasi host dinamis","Internet Control Message":"Pesan kontrol internet","Simple Mail Transfer Protocol":"Transfer surat sederhana","Post Office Protocol v3":"Protokol kantor pos v3","Internet Message Access":"Akses pesan internet","File Transfer Protocol":"Transfer berkas","Secure Shell":"Shell aman","Transport Layer Security":"Keamanan lapisan transport",Internet:"Internet",Client:"Klien",Router:"Router","DNS Resolver":"Resolver DNS","Web Server":"Server web","Root Server":"Server root",".com TLD Server":"Server TLD .com","Authoritative Server":"Server otoritatif","Mail Server":"Server surel","Web Communication":"Komunikasi web",Request:"Permintaan",Response:"Respons","Data ACKs not shown":"ACK data tidak ditampilkan","HTTP is the protocol of the web: a client asks for a resource, such as an HTML page, and the server answers with a status code, headers and usually a body. Every exchange is one request and one response, written as readable text in HTTP/1.1.":"HTTP adalah protokol web: klien meminta sebuah sumber daya, misalnya halaman HTML, dan server menjawab dengan kode status, header, dan biasanya sebuah body. Setiap pertukaran terdiri dari satu permintaan dan satu respons, yang di HTTP/1.1 ditulis sebagai teks yang bisa dibaca.",Layer:"Lapisan","Application (Layer 7)":"Aplikasi (lapisan 7)","Default Port":"Port bawaan",Transport:"Transport","Data Format":"Format data","Text (headers + optional body)":"Teks (header + body opsional)","Common Methods":"Metode umum","Defined In":"Didefinisikan di","Page delivered":"Halaman terkirim","One request, one response":"Satu permintaan, satu respons","In under a tenth of a second the laptop looked up an address, opened a TCP connection and exchanged one HTTP request and response, all of it readable by anyone on the path. Press REPLAY to watch it again.":"Dalam kurang dari sepersepuluh detik, laptop mencari sebuah alamat, membuka koneksi TCP, dan bertukar satu permintaan dan respons HTTP, semuanya bisa dibaca siapa pun di sepanjang jalur. Tekan ULANGI untuk menontonnya lagi.","Round trips":"Perjalanan pulang-pergi","Total time":"Total waktu","Page size":"Ukuran halaman","Sent as 9 TCP segments":"Dikirim dalam 9 segmen TCP","Client Request":"Permintaan klien","Browser prepares the request":"Browser menyiapkan permintaan","You open http://www.example.com. The browser will send a GET request, but packets travel to IP addresses, not names, so first it needs the server’s address. (Browsers now try https:// first; this is the plain version.)":"Anda membuka http://www.example.com. Browser akan mengirim permintaan GET, tetapi paket dikirim ke alamat IP, bukan ke nama, jadi browser terlebih dulu butuh alamat server. (Browser kini mencoba https:// lebih dulu; ini versi tanpa enkripsi.)",Method:"Metode","Next hop":"Hop berikutnya","Router 192.168.1.1":"Router 192.168.1.1","DNS Resolution":"Resolusi DNS","Finds the server’s IP address":"Menemukan alamat IP server","The laptop asks the DNS server it was given by DHCP, 8.8.8.8, for the address of www.example.com. The query goes over UDP port 53 and the answer is an A record with the IPv4 address. (On a network with IPv6 it would also ask for an AAAA record.)":"Laptop menanyakan alamat www.example.com kepada server DNS yang diberikan DHCP, yaitu 8.8.8.8. Kueri lewat port UDP 53 dan jawabannya berupa record A berisi alamat IPv4. (Di jaringan dengan IPv6, laptop juga akan meminta record AAAA.)",Resolver:"Resolver","8.8.8.8 (had it cached)":"8.8.8.8 (sudah ada di cache)","UDP, port 53":"UDP, port 53",Answer:"Jawaban","TCP Connection":"Koneksi TCP","Establishes a reliable link":"Membangun tautan yang andal","HTTP runs on top of TCP. Before any page data moves, the laptop and the server open a connection to port 80 with a three-way handshake: SYN, SYN-ACK, ACK.":"HTTP berjalan di atas TCP. Sebelum data halaman apa pun bergerak, laptop dan server membuka koneksi ke port 80 dengan three-way handshake: SYN, SYN-ACK, ACK.","Server port":"Port server","Client port":"Port klien",Handshake:"Handshake","HTTP Exchange":"Pertukaran HTTP","Request and response messages":"Pesan permintaan dan respons","The browser sends a GET request with a Host header. The server answers 200 OK with the HTML in the body: 12.2 KB, too big for one packet, so TCP splits it into 9 segments of up to 1460 bytes (drawn here as one).":"Browser mengirim permintaan GET dengan header Host. Server menjawab 200 OK dengan HTML di body: 12.2 KB, terlalu besar untuk satu paket, jadi TCP memecahnya menjadi 9 segmen berukuran paling banyak 1460 byte (di sini digambar sebagai satu).",Status:"Status",Body:"Body","Sent as":"Dikirim sebagai","12.2 KB in 9 segments":"12.2 KB dalam 9 segmen","Page Rendering":"Merender halaman","Browser displays the content":"Browser menampilkan isinya","The browser parses the HTML and paints the page. Linked CSS, images and scripts would each start more requests just like this one, reusing the open connection where they can.":"Browser mengurai HTML dan menggambar halaman. Setiap CSS, gambar, dan skrip yang ditautkan akan memulai permintaan lain seperti ini, dan memakai ulang koneksi yang terbuka bila bisa.",Document:"Dokumen",Connection:"Koneksi","Kept open for reuse":"Tetap terbuka untuk dipakai ulang","Seen on the laptop’s home network":"Terlihat di jaringan rumah laptop",Destination:"Tujuan","The router: anything beyond the home network goes to it first.":"Router: semua yang keluar dari jaringan rumah lewat router lebih dulu.",Source:"Sumber","The laptop’s network card.":"Kartu jaringan laptop.",Type:"Tipe","What the frame carries.":"Apa yang dibawa frame ini.","Version, header length":"Versi, panjang header","IPv4, with no options.":"IPv4, tanpa opsi.","Priority and congestion marks; 0 means ordinary traffic.":"Tanda prioritas dan kemacetan; 0 berarti lalu lintas biasa.","Total length":"Panjang total","This header and everything inside it.":"Header ini dan semua isinya.",Identification:"Identifikasi","Lets the receiver reassemble the pieces if the packet gets split.":"Memungkinkan penerima menyusun ulang potongan jika paket dipecah.",Flags:"Flag",none:"tidak ada","Routers may split it if a link is too small.":"Router boleh memecahnya jika sebuah tautan terlalu kecil.","Time to live":"Time to live","Windows starts at 128.":"Windows mulai dari 128.",Protocol:"Protokol","Header checksum":"Checksum header","Covers this header only; every router recomputes it after lowering the TTL.":"Hanya mencakup header ini; setiap router menghitungnya ulang setelah menurunkan TTL.","Source port":"Port sumber","Destination port":"Port tujuan",Length:"Panjang","UDP header and data. That is all of UDP: no numbering, no acknowledgements.":"Header UDP dan data. Itulah seluruh UDP: tanpa penomoran, tanpa pengakuan.",Checksum:"Checksum","Covers the header, the data and the IP addresses.":"Mencakup header, data, dan alamat IP.","Transaction ID":"ID transaksi","Picked at random; the answer must carry the same one.":"Dipilih acak; jawabannya harus membawa ID yang sama.","0x0100: query, RD (recursion desired)":"0x0100: kueri, RD (rekursi diinginkan)",Questions:"Pertanyaan",Answers:"Jawaban","Authority records":"Record otoritas","Additional records":"Record tambahan",Question:"Pertanyaan","www.example.com, type A, class IN":"www.example.com, tipe A, kelas IN","The laptop.":"Laptop.","The router’s side facing the home network.":"Sisi router yang menghadap jaringan rumah.","Started at 128; 10 routers on the way each took 1.":"Mulai dari 128; masing-masing dari 10 router di jalan mengurangi 1.","0x8180: response, RD (recursion desired), RA (recursion available)":"0x8180: respons, RD (rekursi diinginkan), RA (rekursi tersedia)","DF (don’t fragment)":"DF (jangan fragmentasi)","Routers must not split it; if it’s too big they report back instead.":"Router tidak boleh memecahnya; jika terlalu besar, router melapor balik.","Picked by the laptop’s system for this connection.":"Dipilih sistem laptop untuk koneksi ini.","Sequence number":"Nomor urut","This side’s starting number. Shown as 0; the real one is random.":"Nomor awal sisi ini. Ditampilkan sebagai 0; yang asli acak.","Real sequence number":"Nomor urut asli",Acknowledgment:"Pengakuan","0 (not used yet)":"0 (belum dipakai)","A first SYN has nothing to acknowledge.":"SYN pertama belum punya apa pun untuk diakui.","Header length":"Panjang header","20 bytes, plus 12 of options.":"20 byte, ditambah 12 byte opsi.",Window:"Jendela","How much more data this side can take right now.":"Berapa banyak lagi data yang bisa diterima sisi ini sekarang.","Covers the header, the data and the IP addresses, so damage is caught.":"Mencakup header, data, dan alamat IP, sehingga kerusakan ketahuan.","Urgent pointer":"Urgent pointer",Options:"Opsi","Maximum segment size":"Ukuran segmen maksimum","The most data this side wants in one segment.":"Data terbanyak yang diinginkan sisi ini dalam satu segmen.","Spacing, so the next option lines up.":"Pengisi, agar opsi berikutnya sejajar.","Window scale":"Skala jendela","Window values are multiplied by this, so windows can be larger than 64 KB.":"Nilai jendela dikalikan dengan ini, sehingga jendela bisa lebih dari 64 KB.","SACK permitted":"SACK diizinkan",yes:"ya","This side understands selective acknowledgements.":"Sisi ini memahami pengakuan selektif.","Started at 64; 12 routers on the way each took 1.":"Mulai dari 64; masing-masing dari 12 router di jalan mengurangi 1.","The next byte this side expects: everything before it has arrived.":"Byte berikutnya yang ditunggu sisi ini: semua sebelumnya sudah tiba.","Position of this segment’s first byte, counted from this side’s SYN.":"Posisi byte pertama segmen ini, dihitung dari SYN sisi ini.",Padding:"Padding","Ethernet frames are at least 60 bytes (64 with the checksum the card adds), so short ones are padded.":"Frame Ethernet paling sedikit 60 byte (64 dengan checksum yang ditambahkan kartu), jadi frame yang pendek diberi padding.",Text:"Teks","covers bytes not shown here":"mencakup byte yang tidak ditampilkan di sini","12,500 bytes: the HTML page":"12,500 byte: halaman HTML","The page itself; its contents are not part of the lesson.":"Halaman itu sendiri; isinya bukan bagian dari pelajaran.","Secure Web":"Web aman","TLS handshake":"Handshake TLS","HTTP request":"Permintaan HTTP","HTTP response":"Respons HTTP","HTTPS is HTTP sent through an encrypted TLS connection. TLS proves the server is who it claims to be with a certificate, agrees on fresh encryption keys, and then protects every request and response from being read or changed on the way.":"HTTPS adalah HTTP yang dikirim melalui koneksi TLS terenkripsi. TLS membuktikan dengan sertifikat bahwa server memang yang diakuinya, menyepakati kunci enkripsi baru, lalu melindungi setiap permintaan dan respons agar tidak dibaca atau diubah di jalan.","Application (HTTP over TLS)":"Aplikasi (HTTP di atas TLS)",Security:"Keamanan","TLS 1.3 (1.2 still common)":"TLS 1.3 (1.2 masih umum)",Proves:"Membuktikan","Server identity (certificate)":"Identitas server (sertifikat)","Secure page delivered":"Halaman aman terkirim","Encrypted, except the lookup":"Terenkripsi, kecuali pencarian DNS","The browser looked up the address in plain DNS, opened a TCP connection, checked the server’s certificate and agreed on keys in one round trip. Every HTTP byte after that travelled encrypted. Press REPLAY to watch it again.":"Browser mencari alamat lewat DNS tanpa enkripsi, membuka koneksi TCP, memeriksa sertifikat server, dan menyepakati kunci dalam satu perjalanan pulang-pergi. Setiap byte HTTP sesudahnya berjalan terenkripsi. Tekan ULANGI untuk menontonnya lagi.",Cipher:"Cipher","Still visible":"Masih terlihat","IPs, server name, sizes":"IP, nama server, ukuran","Secure Request":"Permintaan aman","Browser asks for https://":"Browser meminta https://","You type https://www.example.com. The “s” tells the browser to protect the connection with TLS, on port 443 by default. Before it can connect at all, it still has to find the server’s IP address.":"Anda mengetik https://www.example.com. Huruf “s” memberi tahu browser untuk melindungi koneksi dengan TLS, secara bawaan di port 443. Sebelum bisa terhubung, browser tetap harus menemukan alamat IP server.",Port:"Port","DNS Lookup":"Pencarian DNS","Same lookup as HTTP, not encrypted":"Pencarian yang sama seperti HTTP, tanpa enkripsi","The lookup is exactly the same as for plain HTTP: a query to 8.8.8.8 over UDP port 53. It is not encrypted, so anyone on the path can see which name you asked for, unless the browser uses DNS over HTTPS.":"Pencariannya persis sama dengan HTTP biasa: kueri ke 8.8.8.8 lewat port UDP 53. Kueri ini tidak terenkripsi, jadi siapa pun di jalur bisa melihat nama yang Anda tanyakan, kecuali browser memakai DNS over HTTPS.",Encrypted:"Terenkripsi","No (plain DNS)":"Tidak (DNS biasa)","TCP Handshake":"Handshake TCP","Opens a connection to port 443":"Membuka koneksi ke port 443","TLS rides on TCP, so the same three-way handshake comes first, this time to port 443. Nothing is encrypted yet.":"TLS berjalan di atas TCP, jadi three-way handshake yang sama datang lebih dulu, kali ini ke port 443. Belum ada yang terenkripsi.","TLS Handshake":"Handshake TLS","Agrees on keys, checks the certificate":"Menyepakati kunci, memeriksa sertifikat","The browser offers ciphers and key shares, including a post-quantum hybrid. The server picks it and sends its own share, then its certificate, already encrypted. The browser checks it against authorities it trusts.":"Browser menawarkan cipher dan key share, termasuk hibrida pascakuantum. Server memilihnya dan mengirim key share miliknya, lalu sertifikatnya, yang sudah terenkripsi. Browser memeriksanya terhadap otoritas yang dipercayainya.",Version:"Versi","Key exchange":"Pertukaran kunci","X25519MLKEM768 (hybrid)":"X25519MLKEM768 (hibrida)","Server name":"Nama server","Sent in clear (SNI)":"Dikirim tanpa enkripsi (SNI)","key shares: hybrid + x25519":"key share: hibrida + x25519","cipher: AES_128_GCM_SHA256":"cipher: AES_128_GCM_SHA256","then encrypted: cert, Finished":"lalu terenkripsi: sertifikat, Finished","handshake complete (encrypted)":"handshake selesai (terenkripsi)","Encrypted Exchange":"Pertukaran terenkripsi","HTTP inside TLS records":"HTTP di dalam record TLS","The GET and 200 OK are the same HTTP messages as before, sealed in TLS records that look like random “application data” on the wire. The server also hands over two session tickets, so a later visit can skip part of the handshake.":"GET dan 200 OK adalah pesan HTTP yang sama seperti tadi, disegel dalam record TLS yang di jaringan tampak seperti “data aplikasi” acak. Server juga memberikan dua session ticket, supaya kunjungan berikutnya bisa melewati sebagian handshake.",Inside:"Di dalam","GET / and 200 OK":"GET / dan 200 OK",Tickets:"Tiket","2, for faster reconnects":"2, untuk menyambung ulang lebih cepat","inside: GET / HTTP/1.1":"di dalam: GET / HTTP/1.1","outside: encrypted bytes":"di luar: byte terenkripsi","inside: HTTP/1.1 200 OK":"di dalam: HTTP/1.1 200 OK","outside: 12.9 KB, 9 segments":"di luar: 12.9 KB, 9 segmen","Browser shows the padlock":"Browser menampilkan gembok","The browser decrypts the response, paints the page and shows a padlock: the connection is private and the server proved its identity. The Strict-Transport-Security header tells it to use HTTPS for this site from now on.":"Browser mendekripsi respons, menggambar halaman, dan menampilkan gembok: koneksinya privat dan server telah membuktikan identitasnya. Header Strict-Transport-Security memberi tahu browser untuk memakai HTTPS di situs ini mulai sekarang.",Remembers:"Mengingat","HTTPS only (HSTS), 1 year":"Hanya HTTPS (HSTS), 1 tahun","Server Hello + encrypted handshake, 3 segments":"Server Hello + handshake terenkripsi, 3 segmen","Change Cipher Spec, Finished (encrypted)":"Change Cipher Spec, Finished (terenkripsi)","Application Data (HTTP request)":"Application Data (permintaan HTTP)","New Session Ticket ×2 (encrypted)":"New Session Ticket ×2 (terenkripsi)","Application Data (HTTP response), 9 segments":"Application Data (respons HTTP), 9 segmen",Record:"Record","Content type":"Tipe konten","A Client Hello’s record says TLS 1.0 so old middleboxes let it through; the real versions are offered inside.":"Record dari Client Hello menyebut TLS 1.0 agar middlebox lama meloloskannya; versi yang sebenarnya ditawarkan di dalam.","Handshake type":"Tipe handshake",Contents:"Isi","Everything the browser supports. Browsers vary a few details from one connection to the next.":"Semua yang didukung browser. Browser mengubah sedikit detail dari satu koneksi ke koneksi lain.","Server name (SNI)":"Nama server (SNI)","Versions offered":"Versi yang ditawarkan","Key shares":"Key share","App protocols (ALPN)":"Protokol aplikasi (ALPN)","TLS 1.3 records say 1.2 on the outside, for compatibility.":"Record TLS 1.3 menyebut 1.2 di bagian luar, demi kompatibilitas.","The server’s choices and its half of the hybrid key exchange.":"Pilihan server dan bagiannya dalam pertukaran kunci hibrida.","Cipher suite":"Cipher suite","Key share":"Key share","Has no job in TLS 1.3; sent so middleboxes see a familiar handshake.":"Tidak punya fungsi di TLS 1.3; dikirim agar middlebox melihat handshake yang familier.","Every encrypted record says Application Data on the outside; the real type is inside.":"Setiap record terenkripsi menyebut Application Data di bagian luar; tipe sebenarnya ada di dalam.","Encrypted data":"Data terenkripsi","Ciphertext, ending in a 16-byte tag that shows any change. Only the two ends can read it.":"Ciphertext, diakhiri tag 16 byte yang memperlihatkan setiap perubahan. Hanya kedua ujung yang bisa membacanya.","Encrypted Extensions (ALPN: http/1.1), Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions (ALPN: http/1.1), Certificate (rantainya), Certificate Verify (tanda tangannya), Finished","Finished: a check value over the whole handshake":"Finished: nilai pemeriksaan atas seluruh handshake","The HTTP request":"Permintaan HTTP","New Session Ticket: lets a later visit resume":"New Session Ticket: memungkinkan kunjungan berikutnya melanjutkan sesi","The HTTP response, then the 12,500-byte page":"Respons HTTP, lalu halaman 12,500 byte","Reliable Delivery":"Pengiriman andal","Handshake and ACKs":"Handshake dan ACK","Data from laptop":"Data dari laptop","Data from server":"Data dari server","Closing (FIN)":"Penutupan (FIN)","TCP turns the internet’s best-effort packet delivery into a reliable, ordered stream of bytes. It numbers every byte, acknowledges what arrives, resends what goes missing, and paces the sender so neither the other side nor the network is overwhelmed.":"TCP mengubah pengiriman paket internet yang bersifat “best effort” menjadi aliran byte yang andal dan berurutan. TCP menomori setiap byte, mengakui yang tiba, mengirim ulang yang hilang, dan mengatur laju pengirim agar sisi lain maupun jaringan tidak kewalahan.","Transport (Layer 4)":"Transport (lapisan 4)","Three-way handshake":"Three-way handshake",Reliability:"Keandalan","Sequence numbers + ACKs":"Nomor urut + ACK",Recovery:"Pemulihan",Retransmission:"Transmisi ulang",Header:"Header","Connection closed":"Koneksi ditutup","Every byte accounted for":"Setiap byte terhitung","TCP opened a connection, numbered and acknowledged every byte, spotted a gap and resent just the missing segment, then closed both directions cleanly. curl received every byte in order and never saw the loss. Press REPLAY to watch it again.":"TCP membuka koneksi, menomori dan mengakui setiap byte, menemukan celah dan hanya mengirim ulang segmen yang hilang, lalu menutup kedua arah dengan rapi. curl menerima setiap byte secara berurutan dan tidak pernah melihat kehilangan itu. Tekan ULANGI untuk menontonnya lagi.",Segments:"Segmen","14 (1 lost, 1 resent)":"14 (1 hilang, 1 dikirim ulang)","Bytes delivered":"Byte terkirim","78 up, 2,920 down":"78 naik, 2,920 turun","Loss found by":"Kehilangan terdeteksi lewat","Duplicate ACK + SACK":"ACK ganda + SACK","Open Connection":"Membuka koneksi","curl already knows the server’s address. Before any data moves, both sides choose a starting sequence number and confirm it: SYN, SYN-ACK, ACK. The numbers here are relative; real ones start at a random value.":"curl sudah tahu alamat server. Sebelum data apa pun bergerak, kedua sisi memilih nomor urut awal dan mengonfirmasinya: SYN, SYN-ACK, ACK. Nomor di sini relatif; nomor sebenarnya dimulai dari nilai acak.",Server:"Server","203.0.113.10, port 80":"203.0.113.10, port 80","Send Data":"Mengirim data","Every byte is numbered":"Setiap byte dinomori","curl sends its 78-byte HTTP request: bytes 1 to 78. The server’s ACK number, 79, is the next byte it expects, which means everything before it has arrived.":"curl mengirim permintaan HTTP-nya yang berukuran 78 byte: byte 1 sampai 78. Nomor ACK dari server, 79, adalah byte berikutnya yang ditunggunya, artinya semua sebelumnya sudah tiba.",Sent:"Terkirim","79 = next byte expected":"79 = byte berikutnya yang ditunggu","Two Segments Back":"Dua segmen kembali","One of them is lost":"Salah satunya hilang","The server answers with 2,920 bytes: two full segments of 1,460 bytes, the most that fits in one packet here, sent back to back. The first is dropped somewhere on the internet; the second gets through.":"Server menjawab dengan 2,920 byte: dua segmen penuh berukuran 1,460 byte, jumlah terbanyak yang muat dalam satu paket di sini, dikirim berturut-turut. Yang pertama jatuh di suatu tempat di internet; yang kedua sampai.","Segment 1":"Segmen 1","bytes 1–1460 (lost)":"byte 1–1460 (hilang)","Segment 2":"Segmen 2","Segment size":"Ukuran segmen","seq=1 and seq=1461":"seq=1 dan seq=1461","the first is lost":"yang pertama hilang","A Gap Is Noticed":"Celah terdeteksi","Duplicate ACK with SACK":"ACK ganda dengan SACK","Bytes 1461–2920 arrive, but 1–1460 never did. An ACK can only count bytes received in order, so the laptop repeats ACK 1 at once and adds a SACK block saying it already holds 1461–2920.":"Byte 1461–2920 tiba, tetapi 1–1460 tidak pernah sampai. ACK hanya bisa menghitung byte yang diterima berurutan, jadi laptop segera mengulang ACK 1 dan menambahkan blok SACK yang menyatakan bahwa ia sudah punya 1461–2920.","1 (still waiting for byte 1)":"1 (masih menunggu byte 1)","holds bytes 1461–2920":"punya byte 1461–2920","At once, not delayed":"Segera, tanpa ditunda","sack: has 1461–2920":"sack: punya 1461–2920","Resend the Gap":"Mengirim ulang celah","Only the missing bytes":"Hanya byte yang hilang","The SACK tells the server exactly what is missing, so it resends just segment 1, and the laptop acknowledges everything. Had no ACK come back at all, timers would have stepped in: a probe after about two round trips, then a retransmission timeout (at least 200 ms on Linux).":"SACK memberi tahu server persis apa yang hilang, jadi server hanya mengirim ulang segmen 1, dan laptop mengakui semuanya. Kalau sama sekali tidak ada ACK yang kembali, timer yang akan bertindak: lebih dulu probe setelah sekitar dua kali bolak-balik, lalu batas waktu transmisi ulang (minimal 200 ms di Linux).",Resent:"Dikirim ulang","bytes 1–1460 only":"hanya byte 1–1460","Next ACK":"ACK berikutnya","2921 (everything)":"2921 (semuanya)","curl saw":"Yang dilihat curl","Every byte, in order":"Setiap byte, berurutan","just the missing segment":"hanya segmen yang hilang","Close Connection":"Menutup koneksi","Each side says goodbye":"Tiap sisi berpamitan","curl is done, so it closes. Each direction closes on its own: the laptop sends FIN and the server acknowledges it, then the server sends its own FIN and the laptop acknowledges that. The laptop keeps the connection’s details for a while (TIME-WAIT).":"curl sudah selesai, jadi ia menutup koneksi. Setiap arah ditutup sendiri-sendiri: laptop mengirim FIN dan server mengakuinya, lalu server mengirim FIN-nya sendiri dan laptop mengakuinya. Laptop menyimpan detail koneksi untuk sementara (TIME-WAIT).","Closed by":"Ditutup dengan","A FIN from each side":"Satu FIN dari tiap sisi",Order:"Urutan",Then:"Lalu","Laptop waits (TIME-WAIT)":"Laptop menunggu (TIME-WAIT)",Data:"Data","1,460 bytes: the HTTP response, bytes 1–1460":"1,460 byte: respons HTTP, byte 1–1460","1,460 bytes: the HTTP response, bytes 1461–2920":"1,460 byte: respons HTTP, byte 1461–2920","has 1461–2920":"punya 1461–2920","Bytes that arrived after the gap, so only the gap needs resending.":"Byte yang tiba setelah celah, jadi hanya celah itu yang perlu dikirim ulang.","Fast Datagrams":"Datagram cepat","Your voice":"Suara Anda","Their voice":"Suara lawan bicara","Media Server":"Server media","UDP sends data in independent packets called datagrams, with no connection, no acknowledgements and no resends. That keeps it fast and light: right for voice, video, games and DNS, where a late answer is worse than a missing one.":"UDP mengirim data dalam paket-paket independen yang disebut datagram, tanpa koneksi, tanpa konfirmasi, dan tanpa pengiriman ulang. Itu membuatnya cepat dan ringan: cocok untuk suara, video, game, dan DNS, di mana jawaban yang terlambat lebih buruk daripada jawaban yang hilang.",None:"Tidak ada","None (no ACKs, no resends)":"Tidak ada (tanpa ACK, tanpa pengiriman ulang)",Ordering:"Urutan","Not guaranteed":"Tidak dijamin","Call keeps flowing":"Panggilan terus berjalan","Fast, simple, no guarantees":"Cepat, sederhana, tanpa jaminan","Audio started with the very first packet, every datagram travelled on its own, and the one that was lost was simply gone: UDP never noticed. The app covered the gap and the call carried on. Press REPLAY to watch it again.":"Audio dimulai sejak paket pertama, setiap datagram berjalan sendiri-sendiri, dan yang hilang ya hilang begitu saja: UDP tidak pernah menyadarinya. Aplikasi menutupi celahnya dan panggilan terus berlanjut. Tekan ULANGI untuk menontonnya lagi.",Datagrams:"Datagram","11 (1 lost, never resent)":"11 (1 hilang, tidak pernah dikirim ulang)","Setup time":"Waktu penyiapan","0 ms (no handshake)":"0 ms (tanpa handshake)",Shown:"Ditampilkan","The first 0.2 s of a call":"0.2 detik pertama sebuah panggilan","Send Right Away":"Langsung kirim","No handshake, data goes first":"Tanpa handshake, data langsung dikirim","A call app already knows the media server’s address and port from signing in. It doesn’t open a connection: the very first datagram already carries 20 ms of your voice, behind an 8-byte UDP header.":"Aplikasi panggilan sudah tahu alamat dan port server media sejak Anda masuk. Aplikasi tidak membuka koneksi: datagram pertama pun sudah membawa 20 ms suara Anda, di belakang header UDP 8 byte.",Setup:"Penyiapan",Ports:"Port","92 B of audio, no setup":"92 B audio, tanpa penyiapan","A Stream of Datagrams":"Aliran datagram","One every 20 ms, each on its own":"Satu setiap 20 ms, masing-masing sendiri","The app keeps sending a datagram every 20 ms. Each one stands alone, with its own header and no link to the others. UDP doesn’t number them, and nothing comes back to confirm they arrived.":"Aplikasi terus mengirim satu datagram setiap 20 ms. Masing-masing berdiri sendiri, dengan header sendiri dan tanpa kaitan dengan yang lain. UDP tidak menomorinya, dan tidak ada yang kembali untuk memastikan datagram itu sampai.",Rate:"Laju","1 datagram / 20 ms":"1 datagram / 20 ms",Numbering:"Penomoran","None in UDP itself":"Tidak ada di UDP itu sendiri",Confirmation:"Konfirmasi","None (no ACKs)":"Tidak ada (tanpa ACK)","voice frames 2–5":"frame suara 2–5","each with its own 8-byte header":"masing-masing dengan header 8 byte sendiri","Lost on the Way":"Hilang di jalan","Nobody resends it":"Tidak ada yang mengirim ulang","Frame 7 is dropped somewhere on the internet. The media server never asks for it, and UDP never tells the laptop: there are no acknowledgements to miss. The datagrams after it arrive as normal.":"Frame 7 terbuang di suatu tempat di internet. Server media tidak pernah memintanya, dan UDP tidak pernah memberi tahu laptop: tidak ada konfirmasi yang bisa terasa hilang. Datagram setelahnya tiba seperti biasa.",Lost:"Hilang","Voice frame 7":"Frame suara 7","Never (no ACKs)":"Tidak pernah (tanpa ACK)",Missing:"Terlewat","20 ms of audio":"20 ms audio","voice frames 6–8":"frame suara 6–8","frame 7 is lost":"frame 7 hilang","Replies Come Back":"Balasan kembali","The other voice comes back":"Suara lawan bicara kembali","The other person’s voice arrives the same way, as separate datagrams sent to port 50000. They get back in because your router remembered the outgoing port when it translated your address (NAT).":"Suara lawan bicara tiba dengan cara yang sama, sebagai datagram-datagram terpisah yang dikirim ke port 50000. Datagram itu bisa masuk karena router Anda mengingat port keluar saat menerjemahkan alamat Anda (NAT).",Direction:"Arah","Independent of ours":"Tidak bergantung pada arah kita","Through NAT":"Melewati NAT","Router remembers the port":"Router mengingat port-nya","the other person’s voice":"suara lawan bicara","sent to port 50000":"dikirim ke port 50000","The App Decides":"Aplikasi yang menentukan","Reliability is up to the app":"Keandalan diserahkan ke aplikasi","The call app numbers its own frames (RTP does this), so it sees that frame 7 is missing and smooths over the 20 ms gap instead of waiting. Waiting for a resend would make the whole call lag.":"Aplikasi panggilan menomori frame-nya sendiri (itulah tugas RTP), jadi ia melihat bahwa frame 7 hilang dan menyamarkan celah 20 ms itu alih-alih menunggu. Menunggu pengiriman ulang akan membuat seluruh panggilan tersendat.","App’s job (e.g. RTP)":"Tugas aplikasi (mis. RTP)",Loss:"Kehilangan","Hidden by the app":"Disembunyikan oleh aplikasi","Also on UDP":"Juga lewat UDP","DNS, games, QUIC":"DNS, game, QUIC","Version etc.":"Versi dll.","2, no padding, no extension, no CSRCs":"2, tanpa padding, tanpa ekstensi, tanpa CSRC","Marker, payload type":"Marker, jenis payload","1, 111 (Opus, agreed when the call was set up)":"1, 111 (Opus, disepakati saat panggilan disiapkan)","Counts up by one per packet, so the app can spot a missing or late one.":"Bertambah satu per paket, agar aplikasi bisa mengenali paket yang hilang atau terlambat.",Timestamp:"Stempel waktu","Audio clock at 48,000 per second: +960 per 20 ms frame.":"Jam audio 48,000 per detik: +960 per frame 20 ms.","Identifies this audio stream.":"Mengidentifikasi aliran audio ini.",Audio:"Audio","80 bytes of Opus audio (20 ms)":"80 byte audio Opus (20 ms)","0, 111 (Opus, agreed when the call was set up)":"0, 111 (Opus, disepakati saat panggilan disiapkan)","Addressing & Routing":"Pengalamatan & perutean","Outgoing packet":"Paket keluar",Reply:"Balasan","IP gives every device an address and moves packets from network to network. Each router looks only at the destination address to choose the next hop. IP is best effort: it doesn’t promise delivery or order. TCP adds those on top.":"IP memberi setiap perangkat sebuah alamat dan memindahkan paket dari jaringan ke jaringan. Setiap router hanya melihat alamat tujuan untuk memilih hop berikutnya. IP bersifat best effort: tidak menjanjikan pengiriman maupun urutan. TCP menambahkan keduanya di atasnya.","Network (Layer 3)":"Jaringan (lapisan 3)",Address:"Alamat","Lowered by 1 at each router":"Dikurangi 1 di setiap router",Delivery:"Pengiriman","Best effort":"Best effort","There and back":"Pergi dan pulang","Twelve routers each way":"Dua belas router di setiap arah","The laptop sent the packet to its router, which swapped in its public address. Twelve routers in all passed it along by destination address alone, and the reply found its way back the same way. Press REPLAY to watch it again.":"Laptop mengirim paket ke router-nya, yang memasang alamat publiknya sendiri. Total dua belas router meneruskannya hanya berdasarkan alamat tujuan, dan balasannya menemukan jalan pulang dengan cara yang sama. Tekan ULANGI untuk menontonnya lagi.",Routers:"Router","12 each way (1 home + 11)":"12 per arah (1 di rumah + 11)","TTL at server":"TTL di server","116 (sent with 128)":"116 (dikirim dengan 128)","Rewritten by NAT":"Ditulis ulang oleh NAT","Source out, destination back":"Sumber saat pergi, tujuan saat kembali","IPv4 (IPv6 works alike)":"IPv4 (IPv6 bekerja serupa)","Local or Not?":"Lokal atau bukan?","Compare the address with the subnet":"Bandingkan alamat dengan subnet","The laptop is 192.168.1.10 with a /24 mask, so its own network is 192.168.1.0 to 192.168.1.255. The server, 203.0.113.10, is outside that range, so the packet has to go to the default gateway: the home router.":"Laptop beralamat 192.168.1.10 dengan mask /24, jadi jaringannya sendiri mencakup 192.168.1.0 sampai 192.168.1.255. Server, 203.0.113.10, berada di luar rentang itu, jadi paket harus dikirim ke default gateway: router rumah.",Laptop:"Laptop","Local range":"Rentang lokal",Gateway:"Gateway","Find the Router":"Temukan router","ARP turns an IP into a MAC":"ARP mengubah IP menjadi MAC","On the local network, frames are delivered by MAC address. If the router’s MAC isn’t in the laptop’s ARP cache, it broadcasts “who has 192.168.1.1?” and the router answers with its MAC address.":"Di jaringan lokal, frame dikirim berdasarkan alamat MAC. Jika MAC router belum ada di cache ARP laptop, laptop menyiarkan “siapa yang punya 192.168.1.1?” dan router menjawab dengan alamat MAC-nya.",Asks:"Bertanya","Who has 192.168.1.1?":"Siapa yang punya 192.168.1.1?","Sent to":"Dikirim ke","Everyone (broadcast)":"Semua (broadcast)",Learns:"Mengetahui","Router’s MAC address":"Alamat MAC router","who has 192.168.1.1?":"siapa yang punya 192.168.1.1?","tell 192.168.1.10":"beri tahu 192.168.1.10","Send the Packet":"Kirim paketnya","Addresses, TTL and protocol":"Alamat, TTL, dan protokol","The IP header carries the source and destination addresses, a TTL and the protocol inside. Here it holds a TCP SYN to port 443. Windows starts the TTL at 128 (Linux and macOS use 64).":"Header IP membawa alamat sumber dan tujuan, sebuah TTL, dan protokol di dalamnya. Di sini isinya TCP SYN ke port 443. Windows memulai TTL dari 128 (Linux dan macOS memakai 64).","From → to":"Dari → ke","TTL 128 · protocol TCP":"TTL 128 · protokol TCP","NAT, Then Hop by Hop":"NAT, lalu hop demi hop","The router rewrites and forwards":"Router menulis ulang dan meneruskan","The router swaps the private source for its public address 198.51.100.7 (and here port 52344 for 40112), notes the mapping, and lowers the TTL to 127. Then 11 routers on the internet each choose the next hop by destination and lower the TTL again.":"Router mengganti sumber privat dengan alamat publiknya 198.51.100.7 (dan di sini port 52344 dengan 40112), mencatat pemetaannya, lalu menurunkan TTL menjadi 127. Kemudian 11 router di internet masing-masing memilih hop berikutnya berdasarkan tujuan dan menurunkan TTL lagi.","New source":"Sumber baru","Leaves home":"Keluar dari rumah","At the server":"Di server","TTL 116 (11 more hops)":"TTL 116 (11 hop lagi)","TTL 127 · after NAT":"TTL 127 · setelah NAT","The Reply Comes Back":"Balasannya kembali","NAT translates it for the laptop":"NAT menerjemahkannya untuk laptop","The server answers the address it saw, 198.51.100.7:40112. The router looks that up in its NAT table, rewrites the destination back to 192.168.1.10:52344 and passes it on. The reply started at TTL 64 and arrives with 52.":"Server menjawab ke alamat yang dilihatnya, 198.51.100.7:40112. Router mencarinya di tabel NAT, menulis ulang tujuannya kembali menjadi 192.168.1.10:52344, lalu meneruskannya. Balasan berangkat dengan TTL 64 dan tiba dengan 52.","Delivered to":"Diantar ke","TTL 52 · after NAT":"TTL 52 · setelah NAT","TTL 127 · 40112 → 443 [SYN] (after NAT)":"TTL 127 · 40112 → 443 [SYN] (setelah NAT)","TTL 52 · 443 → 52344 [SYN, ACK] (after NAT)":"TTL 52 · 443 → 52344 [SYN, ACK] (setelah NAT)","ARP request · 28 bytes":"Permintaan ARP · 28 byte","Broadcast: every device on the network receives it.":"Broadcast: setiap perangkat di jaringan menerimanya.","The sender’s network card.":"Kartu jaringan pengirim.","Hardware type":"Jenis perangkat keras","Protocol type":"Jenis protokol","Address sizes":"Ukuran alamat",Operation:"Operasi","1 (request: who has …?)":"1 (permintaan: siapa yang punya …?)","Sender MAC":"MAC pengirim","Sender IP":"IP pengirim","Target MAC":"MAC target","All zeros: this is what the request wants to find out.":"Semuanya nol: inilah yang ingin diketahui permintaan ini.","Target IP":"IP target","ARP reply · 28 bytes":"Balasan ARP · 28 byte","Straight back to the device that asked.":"Langsung kembali ke perangkat yang bertanya.","2 (reply: … is at …)":"2 (balasan: … ada di …)","Seen as it leaves the router’s internet side":"Terlihat saat keluar dari sisi internet router","The internet provider’s router, the next hop.":"Router penyedia internet, hop berikutnya.","The router’s internet-facing port.":"Port router yang menghadap internet.","As sent: this system starts at 64.":"Seperti saat dikirim: sistem ini mulai dari 64.","The router’s NAT swapped in its own port for the laptop’s.":"NAT router mengganti port laptop dengan port miliknya sendiri.","The sender’s next router; each hop puts the packet in a new frame.":"Router berikutnya milik pengirim; di setiap hop paket dimasukkan ke frame baru.","Name Resolution":"Resolusi nama",Query:"Kueri",Referral:"Rujukan","DNSSEC not requested here":"DNSSEC tidak diminta di sini","DNS turns names like www.example.com into the IP addresses computers use to reach each other. No single server knows every name: the system is a hierarchy of servers, and answers are cached along the way so most lookups never have to go far.":"DNS mengubah nama seperti www.example.com menjadi alamat IP yang dipakai komputer untuk saling menjangkau. Tidak ada satu server pun yang tahu semua nama: sistemnya adalah hierarki server, dan jawaban disimpan di cache sepanjang jalan sehingga sebagian besar pencarian tidak perlu pergi jauh.","53, UDP (TCP if large)":"53, UDP (TCP jika besar)",Turns:"Mengubah","Names into IP addresses":"Nama menjadi alamat IP",Hierarchy:"Hierarki","Root → TLD → authoritative":"Root → TLD → otoritatif",Caching:"Caching","For each record’s TTL":"Selama TTL setiap record","Name resolved":"Nama berhasil diterjemahkan","And remembered for an hour":"Dan diingat selama satu jam","Starting from an empty cache, the resolver walked from the root to .com to example.com’s own server, then answered the laptop. Until the TTL runs out, the next lookup for this name is answered straight from a cache. Press REPLAY to watch it again.":"Berawal dari cache kosong, resolver berjalan dari root ke .com lalu ke server milik example.com sendiri, kemudian menjawab laptop. Sampai TTL habis, pencarian berikutnya untuk nama ini langsung dijawab dari cache. Tekan ULANGI untuk menontonnya lagi.",Queries:"Kueri","4 (laptop 1, resolver 3)":"4 (laptop 1, resolver 3)","Cached for":"Disimpan di cache selama","Ask the Resolver":"Tanya resolver","The laptop hands the question off":"Laptop menyerahkan pertanyaannya","The browser needs the IP address of www.example.com and neither it nor Windows has one cached. The laptop sends one question to the recursive resolver it was given, 8.8.8.8, and asks it to do the whole lookup (recursion desired).":"Browser membutuhkan alamat IP www.example.com, dan baik browser maupun Windows tidak menyimpannya di cache. Laptop mengirim satu pertanyaan ke resolver rekursif yang diberikan kepadanya, 8.8.8.8, dan memintanya melakukan seluruh pencarian (rekursi diminta).","www.example.com, type A":"www.example.com, tipe A",Asked:"Ditanyakan ke","8.8.8.8 (recursive)":"8.8.8.8 (rekursif)","RD (recursion desired)":"RD (rekursi diminta)","flags: RD":"flag: RD","Points the way to .com":"Menunjukkan jalan ke .com","The resolver’s cache is empty (it has just started), so it begins at the top. A root server doesn’t know the address, but it knows which servers handle .com and replies with a referral. Many resolvers send it only “com”, not the full name.":"Cache resolver kosong (baru saja dinyalakan), jadi ia mulai dari puncak. Server root tidak tahu alamatnya, tetapi tahu server mana yang menangani .com dan membalas dengan rujukan. Banyak resolver hanya mengirim “com” kepadanya, bukan nama lengkapnya.","Root servers":"Server root","13 names, 1,000+ anycast sites":"13 nama, lebih dari 1,000 lokasi anycast","Referral (13 .com servers)":"Rujukan (13 server .com)","no answer: ask .com":"tanpa jawaban: tanyakan ke .com","Points the way to example.com":"Menunjukkan jalan ke example.com","The resolver asks one of the .com servers. They don’t store addresses for every site either, but they know which name servers each .com domain uses, so this reply is another referral, with those servers’ addresses (glue) attached.":"Resolver bertanya ke salah satu server .com. Server-server itu juga tidak menyimpan alamat setiap situs, tetapi tahu name server mana yang dipakai setiap domain .com, jadi balasan ini adalah rujukan lain, dengan alamat server-server itu (glue) terlampir.",Knows:"Mengetahui","Name servers of .com domains":"Name server domain .com","Referral + glue addresses":"Rujukan + alamat glue","no answer: ask example.com":"tanpa jawaban: tanyakan ke example.com","Gives the actual answer":"Memberi jawaban sebenarnya","Finally the resolver asks example.com’s own name server, which holds the domain’s records. It answers with the A record and marks the reply authoritative. The domain owner sets how long it may be cached: here, 3600 seconds.":"Akhirnya resolver bertanya ke name server milik example.com sendiri, yang menyimpan record domain tersebut. Server itu menjawab dengan record A dan menandai balasannya sebagai otoritatif. Pemilik domain menentukan berapa lama jawaban boleh disimpan di cache: di sini, 3600 detik.","AA (authoritative), TTL 3600":"AA (otoritatif), TTL 3600","TTL 3600 · flag AA":"TTL 3600 · flag AA","Answer & Cache":"Jawaban & cache","The laptop gets its address":"Laptop mendapatkan alamatnya","The resolver sends the answer back to the laptop and keeps a copy. For the next hour it can answer this name straight away, which is why the lookup in the HTTP lesson took only 24 ms. The laptop caches it too.":"Resolver mengirim jawabannya kembali ke laptop dan menyimpan salinannya. Selama satu jam berikutnya, resolver bisa langsung menjawab nama ini; itulah sebabnya pencarian di pelajaran HTTP hanya butuh 24 ms. Laptop juga menyimpannya di cache.","RD, RA (recursion available)":"RD, RA (rekursi tersedia)","Cached by":"Disimpan di cache oleh","Resolver and laptop":"Resolver dan laptop","flags: RD RA":"flag: RD RA","Referral: com. NS ×13 (with glue)":"Rujukan: com. NS ×13 (dengan glue)","Referral: example.com. NS ×2 (with glue)":"Rujukan: example.com. NS ×2 (dengan glue)","Response A 203.0.113.10 (authoritative)":"Respons A 203.0.113.10 (otoritatif)","As sent: this system starts at 128.":"Seperti saat dikirim: sistem ini mulai dari 128.","0x0000: query":"0x0000: kueri","UDP size 1232, DNSSEC OK = 0":"Ukuran UDP 1232, DNSSEC OK = 0","Says how big a UDP answer can be. DNSSEC signatures are not asked for here, to keep the lesson short; a validating resolver like 8.8.8.8 does ask for them.":"Menyatakan seberapa besar jawaban UDP boleh dikirim. Tanda tangan DNSSEC tidak diminta di sini agar pelajarannya tetap singkat; resolver yang memvalidasi seperti 8.8.8.8 memintanya.","0x8000: response":"0x8000: respons",Authority:"Otoritas",Additional:"Tambahan","0x8400: response, AA (authoritative)":"0x8400: respons, AA (otoritatif)","Getting an Address":"Mendapatkan alamat","From the laptop":"Dari laptop","From the DHCP server":"Dari server DHCP","Dynamic Host Configuration Protocol":"Protokol konfigurasi host dinamis","DHCP hands a device everything it needs to use a network: an IP address, the subnet mask, the router to send traffic through and the DNS servers to ask. Addresses are leased for a set time and renewed while the device stays on the network.":"DHCP memberi perangkat semua yang dibutuhkannya untuk memakai jaringan: alamat IP, subnet mask, router untuk mengirim lalu lintas, dan server DNS untuk ditanyai. Alamat dipinjamkan (lease) untuk waktu tertentu dan diperpanjang selama perangkat tetap berada di jaringan.","UDP 67 (server), 68 (client)":"UDP 67 (server), 68 (klien)","Hands out":"Membagikan","IP, mask, gateway, DNS":"IP, mask, gateway, DNS",Exchange:"Pertukaran",Lease:"Lease","Renewed at half its time":"Diperpanjang di separuh waktunya","On the network":"Di jaringan","Leased, and kept up to date":"Mendapat lease, dan selalu diperbarui","Four messages took the laptop from no address to a working configuration, and halfway through the 24-hour lease it renewed it with a direct request to the router. Press REPLAY to watch it again.":"Empat pesan membawa laptop dari tanpa alamat menjadi konfigurasi yang berfungsi, dan di separuh lease 24 jam laptop memperpanjangnya dengan permintaan langsung ke router. Tekan ULANGI untuk menontonnya lagi.",Messages:"Pesan","4 to join, 2 per renewal":"4 untuk bergabung, 2 per perpanjangan","24 h, renewed at 12 h":"24 jam, diperpanjang pada jam ke-12","No Address Yet":"Belum punya alamat","The laptop joins the network":"Laptop bergabung ke jaringan","The laptop has just connected. It has a MAC address built in, but no IP address, no gateway and no DNS server, so it can’t talk to anything beyond its own network yet. It asks for them with DHCP.":"Laptop baru saja terhubung. Laptop punya alamat MAC bawaan, tetapi belum punya alamat IP, gateway, maupun server DNS, jadi belum bisa berbicara dengan apa pun di luar jaringannya sendiri. Laptop memintanya dengan DHCP.","IP address":"Alamat IP","None (uses 0.0.0.0)":"Tidak ada (memakai 0.0.0.0)","MAC address":"Alamat MAC",Needs:"Butuh",Discover:"Discover","Shout to the whole network":"Berseru ke seluruh jaringan","Without an address of its own, the laptop sends from 0.0.0.0 to the broadcast address 255.255.255.255, so every device on the local network receives it. Only DHCP servers answer.":"Tanpa alamat sendiri, laptop mengirim dari 0.0.0.0 ke alamat broadcast 255.255.255.255, sehingga setiap perangkat di jaringan lokal menerimanya. Hanya server DHCP yang menjawab.",From:"Dari","0.0.0.0, UDP port 68":"0.0.0.0, port UDP 68","255.255.255.255, port 67":"255.255.255.255, port 67",Carries:"Membawa","MAC, transaction ID":"MAC, ID transaksi","any DHCP server out there?":"ada server DHCP di sana?",Offer:"Offer","The router proposes an address":"Router menawarkan alamat","The router’s DHCP server picks a free address and offers it with the rest of the settings. The laptop can’t use an IP address yet, so the offer goes straight to its MAC address (some clients ask for a broadcast instead).":"Server DHCP di router memilih alamat yang kosong dan menawarkannya bersama pengaturan lainnya. Laptop belum bisa memakai alamat IP, jadi tawarannya dikirim langsung ke alamat MAC-nya (sebagian klien meminta broadcast sebagai gantinya).",Offered:"Ditawarkan","Gateway, DNS":"Gateway, DNS","offer: 192.168.1.10/24":"tawaran: 192.168.1.10/24","gateway, DNS, lease 24 h":"gateway, DNS, lease 24 jam","Accept, out loud":"Terima, secara terbuka","The laptop asks for the offered address, naming the server it chose. It still broadcasts, so any other DHCP server that made an offer learns it wasn’t picked and can release its address.":"Laptop meminta alamat yang ditawarkan sambil menyebut server yang dipilihnya. Laptop masih memakai broadcast, sehingga server DHCP lain yang sempat menawarkan tahu bahwa ia tidak dipilih dan bisa melepas alamatnya.",Requests:"Meminta","Chosen server":"Server terpilih","I’ll take 192.168.1.10":"Saya ambil 192.168.1.10","from server 192.168.1.1":"dari server 192.168.1.1",Acknowledge:"Acknowledge","The address is the laptop’s":"Alamat itu milik laptop","The server confirms, and the laptop configures its address, mask, gateway and DNS server. Many systems first check with ARP that no other device is already using the address.":"Server mengonfirmasi, lalu laptop mengatur alamat, mask, gateway, dan server DNS-nya. Banyak sistem lebih dulu memeriksa dengan ARP bahwa belum ada perangkat lain yang memakai alamat itu.","DNS server":"Server DNS","192.168.1.10 is yours":"192.168.1.10 milik Anda","for 24 hours":"selama 24 jam",Renew:"Perpanjang","Halfway through the lease":"Di separuh masa lease","Twelve hours later, half the lease has passed. The laptop now has an address, so it asks the router directly to extend the lease, and the router resets it to 24 hours. If the router didn’t answer, it would broadcast at 87.5%.":"Dua belas jam kemudian, separuh masa lease sudah lewat. Laptop sekarang punya alamat, jadi ia meminta router secara langsung untuk memperpanjang lease, dan router mengaturnya kembali menjadi 24 jam. Jika router tidak menjawab, laptop akan memakai broadcast pada 87.5%.",When:"Kapan","50% of lease (T1 = 12 h)":"50% lease (T1 = 12 jam)","The router (unicast)":"Router (unicast)","If unanswered":"Jika tak dijawab","Broadcast at 87.5% (T2)":"Broadcast pada 87.5% (T2)","renew 192.168.1.10":"perpanjang 192.168.1.10","sent straight to 192.168.1.1":"dikirim langsung ke 192.168.1.1","lease renewed":"lease diperpanjang","another 24 hours":"24 jam lagi",Message:"Pesan","1 (request, from a client)":"1 (permintaan, dari klien)",Hardware:"Perangkat keras","Ethernet, 6-byte addresses":"Ethernet, alamat 6 byte",Hops:"Hop","Chosen by the client; every reply repeats it.":"Dipilih oleh klien; setiap balasan mengulanginya.",Seconds:"Detik","0x0000 (unicast replies are fine)":"0x0000 (balasan unicast boleh)","Broadcast flag off: the server may send straight to the client’s MAC address.":"Flag broadcast mati: server boleh mengirim langsung ke alamat MAC klien.","Client address":"Alamat klien","Filled in only when the client already has an address (renewing).":"Diisi hanya jika klien sudah punya alamat (saat perpanjangan).","Your address":"Alamat Anda","The address the server is giving out.":"Alamat yang diberikan server.","Next server":"Server berikutnya","Relay agent":"Agen relay","Client MAC":"MAC klien","Server name, boot file":"Nama server, file boot",empty:"kosong","Magic cookie":"Magic cookie","Marks the options that follow as DHCP.":"Menandai opsi-opsi berikutnya sebagai DHCP.","Message type: 1 (Discover)":"Jenis pesan: 1 (Discover)","Client identifier: 01 00:00:5e:00:53:10":"Pengenal klien: 01 00:00:5e:00:53:10","Host name: alice-laptop":"Nama host: alice-laptop","Vendor class: MSFT 5.0":"Kelas vendor: MSFT 5.0","Parameters wanted: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252":"Parameter yang diminta: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252","2 (reply, from a server)":"2 (balasan, dari server)","Message type: 2 (Offer)":"Jenis pesan: 2 (Offer)","Server identifier: 192.168.1.1":"Pengenal server: 192.168.1.1","Lease time: 86,400 s (24 h)":"Masa lease: 86,400 dtk (24 jam)","Renewal time (T1): 43,200 s (12 h)":"Waktu perpanjangan (T1): 43,200 dtk (12 jam)","Rebinding time (T2): 75,600 s (21 h)":"Waktu rebinding (T2): 75,600 dtk (21 jam)","Subnet mask: 255.255.255.0":"Subnet mask: 255.255.255.0","Broadcast address: 192.168.1.255":"Alamat broadcast: 192.168.1.255","DNS server: 8.8.8.8":"Server DNS: 8.8.8.8","Message type: 3 (Request)":"Jenis pesan: 3 (Request)","Requested address: 192.168.1.10":"Alamat yang diminta: 192.168.1.10","Client FQDN: alice-laptop":"FQDN klien: alice-laptop","Message type: 5 (ACK)":"Jenis pesan: 5 (ACK)","Network Diagnostics":"Diagnostik jaringan","Ping / probe":"Ping / probe","Echo reply":"Balasan echo","Error report":"Laporan galat","Internet Control Message Protocol":"Protokol pesan kontrol internet","ICMP is how the network reports back: a router says a packet’s time ran out, a server says nothing is listening on a port. Tools like ping and traceroute are built from these messages. It travels inside IP but carries no application data.":"ICMP adalah cara jaringan memberi laporan balik: router mengabarkan bahwa waktu sebuah paket habis, server mengabarkan bahwa tidak ada yang mendengarkan di sebuah port. Alat seperti ping dan traceroute dibangun dari pesan-pesan ini. ICMP berjalan di dalam IP tetapi tidak membawa data aplikasi.","Carried in":"Dibawa dalam","IP (protocol 1)":"IP (protokol 1)","A type and a code":"Sebuah jenis dan kode",Tools:"Alat",Often:"Sering","Filtered by firewalls":"Disaring oleh firewall","The network answered":"Jaringan menjawab","Replies, expiries and errors":"Balasan, kedaluwarsa, dan galat","An echo request measured the round trip, packets with a small TTL made each router on the path identify itself, and a closed port was reported straight back. Press REPLAY to watch it again.":"Sebuah echo request mengukur waktu pulang-pergi, paket dengan TTL kecil membuat setiap router di jalur memperkenalkan diri, dan port yang tertutup langsung dilaporkan kembali. Tekan ULANGI untuk menontonnya lagi.","Round trip":"Pulang-pergi",Path:"Jalur","12 routers, server at hop 13":"12 router, server di hop 13","Types used":"Jenis yang dipakai","8, 0, 11 and 3":"8, 0, 11, dan 3","Reply TTL":"TTL balasan",Ping:"Ping","Echo request":"Echo request","“ping -n 1 203.0.113.10” sends one ICMP echo request (plain ping sends four, a second apart): type 8, code 0, with an identifier, a sequence number and 32 bytes of filler. The server’s system answers by itself, no application needed.":"“ping -n 1 203.0.113.10” mengirim satu ICMP echo request (ping biasa mengirim empat, berjarak satu detik): jenis 8, kode 0, dengan sebuah pengenal, nomor urut, dan 32 byte pengisi. Sistem server menjawab sendiri, tanpa perlu aplikasi.","Type, code":"Jenis, kode","8, 0 (echo request)":"8, 0 (echo request)","type 8 · seq 1":"jenis 8 · urut 1","32 bytes of data":"32 byte data","Echo Reply":"Echo reply","Round-trip time":"Waktu pulang-pergi","The server sends back an echo reply, type 0, with the same identifier, sequence number and data. Ping prints the time it took and the TTL the reply arrived with: “bytes=32 time=34ms TTL=52”.":"Server mengirim balik echo reply, jenis 0, dengan pengenal, nomor urut, dan data yang sama. Ping menampilkan lama waktunya dan TTL saat balasan tiba: “bytes=32 time=34ms TTL=52”.","0, 0 (echo reply)":"0, 0 (echo reply)","TTL on arrival":"TTL saat tiba","type 0 · seq 1":"jenis 0 · urut 1","same 32 bytes back":"32 byte yang sama kembali","The first router answers":"Router pertama menjawab","“ping -n 1 -i 1” sends the same request with a TTL of 1. The home router lowers it to 0, so it must drop the packet, and it sends back a Time Exceeded message from its own address: “Reply from 192.168.1.1: TTL expired in transit.”":"“ping -n 1 -i 1” mengirim permintaan yang sama dengan TTL 1. Router rumah menurunkannya menjadi 0, jadi router harus membuang paket itu, lalu mengirim balik pesan Time Exceeded dari alamatnya sendiri: “Reply from 192.168.1.1: TTL expired in transit.”","Sent with":"Dikirim dengan","Dropped by":"Dibuang oleh","11, 0 (time exceeded)":"11, 0 (time exceeded)","echo request":"echo request","expires at the first router":"kedaluwarsa di router pertama","type 11 · from 192.168.1.1":"jenis 11 · dari 192.168.1.1","quotes the dropped header":"mengutip header yang dibuang","The next router answers":"Router berikutnya menjawab","With “-i 2”, the home router lowers the TTL to 1 and forwards it. The first router at the internet provider lowers it to 0 and reports back from 198.51.100.1. The home router translates the report back to the laptop like any reply.":"Dengan “-i 2”, router rumah menurunkan TTL menjadi 1 lalu meneruskannya. Router pertama di penyedia internet menurunkannya menjadi 0 dan melapor balik dari 198.51.100.1. Router rumah menerjemahkan laporan itu kembali ke laptop seperti balasan lainnya.","ISP router 198.51.100.1":"Router ISP 198.51.100.1","expires at the second router":"kedaluwarsa di router kedua","type 11 · from 198.51.100.1":"jenis 11 · dari 198.51.100.1","That’s Traceroute":"Itulah traceroute","TTL 1, 2, 3 … until it arrives":"TTL 1, 2, 3 … sampai tiba","tracert automates this: it raises the TTL by one each time, sends three probes per hop and lists who reports back. Hops 3 to 12 work the same way, and with TTL 13 the request finally reaches the server, which replies normally.":"tracert mengotomatiskan ini: TTL dinaikkan satu setiap kali, tiga probe dikirim per hop, dan siapa pun yang melapor balik dicatat. Hop 3 sampai 12 bekerja dengan cara yang sama, dan dengan TTL 13 permintaan akhirnya mencapai server, yang menjawab seperti biasa.","12 routers, then the server":"12 router, lalu server","Per hop":"Per hop","3 probes":"3 probe","On Linux":"Di Linux","traceroute sends UDP":"traceroute mengirim UDP","enough hops to arrive":"cukup hop untuk tiba","the server itself answers":"server itu sendiri yang menjawab","end of the route":"akhir rute",Unreachable:"Tak terjangkau","Nothing listening on that port":"Tidak ada yang mendengarkan di port itu","An app sends a UDP datagram to port 9999, where nothing is listening. The server can’t deliver it, so it replies with Destination Unreachable, code 3 (port unreachable), quoting the start of the datagram. Many firewalls drop such packets silently instead.":"Sebuah aplikasi mengirim datagram UDP ke port 9999, tempat tidak ada yang mendengarkan. Server tidak bisa mengantarkannya, jadi server membalas dengan Destination Unreachable, kode 3 (port tak terjangkau), sambil mengutip awal datagram tersebut. Banyak firewall justru membuang paket seperti ini diam-diam.","3, 3 (port unreachable)":"3, 3 (port tak terjangkau)","Other codes":"Kode lain","0 net, 1 host, 4 too big":"0 jaringan, 1 host, 4 terlalu besar",Firewalls:"Firewall","Often silent instead":"Sering diam saja","to port 9999":"ke port 9999","nothing listening there":"tidak ada yang mendengarkan","type 3 · code 3":"jenis 3 · kode 3","port unreachable":"port tak terjangkau","ICMP · Echo request":"ICMP · Echo request",Code:"Kode","Covers the whole ICMP message.":"Mencakup seluruh pesan ICMP.",Identifier:"Pengenal","Matches replies to this ping program.":"Mencocokkan balasan dengan program ping ini.","Windows counts up across every ping it sends.":"Windows terus menambah angka ini di setiap ping yang dikirimnya.","Windows ping’s filler: the alphabet, a to w, then again.":"Pengisi dari ping Windows: alfabet dari a sampai w, lalu diulang.","ICMP · Echo reply":"ICMP · Echo reply","Sent back exactly as it came.":"Dikirim balik persis seperti datangnya.","ICMP · Time exceeded (TTL reached 0)":"ICMP · Time exceeded (TTL mencapai 0)","Time exceeded (TTL reached 0)":"Time exceeded (TTL mencapai 0)",Unused:"Tidak dipakai","Original packet":"Paket asli","Its source, destination":"Sumber dan tujuannya","its IP header and first 8 bytes (28 bytes)":"header IP-nya dan 8 byte pertamanya (28 byte)","App data":"Data aplikasi","What the app sent; nothing on the server is listening for it.":"Yang dikirim aplikasi; tidak ada apa pun di server yang menunggunya.","ICMP · Destination unreachable (port unreachable)":"ICMP · Destination unreachable (port tak terjangkau)","Destination unreachable (port unreachable)":"Destination unreachable (port tak terjangkau)","Sending Email":"Mengirim email","SMTP command":"Perintah SMTP","SMTP reply":"Balasan SMTP","SMTP moves email: from your mail app to your provider’s server, and from that server to the recipient’s. It is a conversation of short text commands, each answered with a three-digit reply code. Reading mail is a different job, done with IMAP or POP3.":"SMTP memindahkan email: dari aplikasi email Anda ke server penyedia Anda, dan dari server itu ke server penerima. Isinya percakapan berupa perintah teks pendek, masing-masing dijawab dengan kode balasan tiga digit. Membaca email adalah tugas lain, dilakukan dengan IMAP atau POP3.","465/587 submit, 25 relay":"465/587 pengiriman, 25 relay","TCP, usually with TLS":"TCP, biasanya dengan TLS",Commands:"Perintah",Replies:"Balasan","2xx ok, 3xx go on, 4/5xx error":"2xx oke, 3xx lanjut, 4/5xx galat","Mail delivered":"Email terkirim","Two hops, one message":"Dua langkah, satu pesan","Alice’s app handed the message to her provider over an encrypted, logged-in connection. The provider found Bob’s mail server in DNS and relayed it there, upgrading that link to TLS. It now waits in Bob’s mailbox until he reads it with IMAP or POP3.":"Aplikasi Alice menyerahkan pesan ke penyedianya lewat koneksi terenkripsi yang sudah login. Penyedia menemukan server email Bob di DNS lalu meneruskan pesan ke sana, sambil meningkatkan sambungan itu ke TLS. Pesan itu kini menunggu di kotak surat Bob sampai ia membacanya dengan IMAP atau POP3.","Laptop → provider → Bob’s":"Laptop → penyedia → milik Bob",Submission:"Pengiriman","Port 465, TLS, login":"Port 465, TLS, login",Relay:"Relay","Port 25, STARTTLS":"Port 25, STARTTLS","Checks at Bob’s":"Pemeriksaan di pihak Bob","Connect Securely":"Terhubung dengan aman","Alice presses Send. Her mail app connects to her provider’s submission server, smtp.example.com, on port 465. On this port TLS starts immediately, so the whole SMTP conversation, including her password, is encrypted.":"Alice menekan Kirim. Aplikasi emailnya terhubung ke server pengiriman milik penyedianya, smtp.example.com, di port 465. Di port ini TLS langsung dimulai, jadi seluruh percakapan SMTP, termasuk kata sandinya, terenkripsi.","TLS from the start":"TLS sejak awal","SMTP inside TLS":"SMTP di dalam TLS","Greeting & Login":"Sapaan & login","EHLO, then AUTH":"EHLO, lalu AUTH","The server greets with code 220. The app says EHLO and the server lists what it supports, including AUTH. The app logs in with AUTH PLAIN (user name and password, base64-encoded) and gets 235: authenticated.":"Server menyapa dengan kode 220. Aplikasi mengucapkan EHLO dan server mendaftar apa saja yang didukungnya, termasuk AUTH. Aplikasi login dengan AUTH PLAIN (nama pengguna dan kata sandi, dikodekan base64) dan menerima 235: terautentikasi.",Greeting:"Sapaan",Capabilities:"Kemampuan","Login result":"Hasil login","user and password, base64":"pengguna dan kata sandi, base64","Send the Message":"Kirim pesannya","Envelope, then content":"Amplop dulu, lalu isi","MAIL FROM and RCPT TO are the envelope: sender and recipient. PIPELINING lets all three commands share one packet. After 354 comes the message, ended by a line holding just a dot.":"MAIL FROM dan RCPT TO adalah amplopnya: pengirim dan penerima. PIPELINING memungkinkan ketiga perintah berbagi satu paket. Setelah 354 datang pesannya, diakhiri dengan baris yang hanya berisi sebuah titik.",Envelope:"Amplop","Content ends":"Akhir isi","A line with only “.”":"Baris yang hanya berisi “.”",Result:"Hasil","… message …":"… pesan …","Find Bob’s Server":"Temukan server Bob","An MX lookup in DNS":"Pencarian MX di DNS","Alice’s provider now has to deliver to example.org. It asks DNS for that domain’s MX record, which names the server that accepts its mail, then looks up that server’s address.":"Penyedia Alice sekarang harus mengantarkan ke example.org. Ia menanyakan record MX domain itu ke DNS, yang menyebut server penerima email-nya, lalu mencari alamat server tersebut.","MX record":"Record MX","Asked by":"Ditanyakan oleh","Alice’s provider":"Penyedia Alice","Server to Server":"Server ke server","Port 25, upgraded with STARTTLS":"Port 25, ditingkatkan dengan STARTTLS","The provider connects to mx.example.org on port 25. This conversation starts in plain text: the greeting and EHLO reply advertise STARTTLS, the provider asks for it, gets 220 and both sides switch to TLS.":"Penyedia terhubung ke mx.example.org di port 25. Percakapan ini dimulai dalam teks biasa: sapaan dan balasan EHLO mengiklankan STARTTLS, penyedia memintanya, menerima 220, dan kedua pihak beralih ke TLS.","Starts as":"Dimulai sebagai","Plain text":"Teks biasa",Upgrade:"Peningkatan",Deliver:"Antarkan","The same transaction again":"Transaksi yang sama sekali lagi","With TLS on, the provider repeats EHLO, then the envelope and the message, now with a DKIM signature and a Received header added. Bob’s server checks SPF, DKIM and DMARC and accepts it.":"Dengan TLS aktif, penyedia mengulang EHLO, lalu amplop dan pesannya, kini dengan tanda tangan DKIM dan header Received yang ditambahkan. Server Bob memeriksa SPF, DKIM, dan DMARC lalu menerimanya.","Login needed":"Perlu login","No (server to server)":"Tidak (server ke server)","1,316 bytes (signed)":"1,316 byte (bertanda tangan)","Server Hello + encrypted handshake, 2 segments":"Server Hello + handshake terenkripsi, 2 segmen","250 capabilities (PIPELINING, SIZE, AUTH …)":"250 kemampuan (PIPELINING, SIZE, AUTH …)","AUTH PLAIN (credentials)":"AUTH PLAIN (kredensial)","MAIL FROM, RCPT TO, DATA (pipelined)":"MAIL FROM, RCPT TO, DATA (dipipelinekan)","Message (316 bytes), then “.”":"Pesan (316 byte), lalu “.”","250 capabilities (PIPELINING, STARTTLS …)":"250 kemampuan (PIPELINING, STARTTLS …)","250 capabilities (PIPELINING, SIZE …)":"250 kemampuan (PIPELINING, SIZE …)","Message (1,316 bytes), then “.”":"Pesan (1,316 byte), lalu “.”","What this client supports. Its exact contents vary from client to client; this is an example.":"Apa yang didukung klien ini. Isi persisnya berbeda dari satu klien ke klien lain; ini sebuah contoh.","up to 512 bytes":"hingga 512 byte","The server’s choices and its key share.":"Pilihan server dan bagian kuncinya.","Encrypted Extensions, Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions, Certificate (rantainya), Certificate Verify (tanda tangannya), Finished","Alice’s message (316 bytes), then a line holding only “.”":"Pesan Alice (316 byte), lalu baris yang hanya berisi “.”","example.org, type MX, class IN":"example.org, tipe MX, kelas IN","mx.example.org, type A, class IN":"mx.example.org, tipe A, kelas IN",Timestamps:"Stempel waktu","Used to measure round trips; both sides offered them.":"Dipakai untuk mengukur waktu pulang-pergi; kedua pihak menawarkannya.","The signed message (1,316 bytes), then a line holding only “.”":"Pesan bertanda tangan (1,316 byte), lalu baris yang hanya berisi “.”","Downloading Email":"Mengunduh email","POP3 command":"Perintah POP3","POP3 reply":"Balasan POP3","Post Office Protocol, version 3":"Protokol kantor pos, versi 3","POP3 lets a mail app download messages from a mailbox on a server. It was designed for one device that fetches mail and then removes it from the server. Commands are short words, and every reply starts with +OK or -ERR.":"POP3 memungkinkan aplikasi email mengunduh pesan dari kotak surat di server. Protokol ini dirancang untuk satu perangkat yang mengambil email lalu menghapusnya dari server. Perintahnya berupa kata-kata pendek, dan setiap balasan diawali +OK atau -ERR.",Model:"Model","Download, then delete":"Unduh, lalu hapus","Mail downloaded":"Email terunduh","And gone from the server":"Dan hilang dari server","Bob’s app logged in, saw two messages, downloaded the first and deleted it, which the server carried out at QUIT. That message now lives only on this laptop, which is why POP3 suits one device and IMAP suits several.":"Aplikasi Bob login, melihat dua pesan, mengunduh yang pertama lalu menghapusnya, yang dijalankan server saat QUIT. Pesan itu kini hanya ada di laptop ini; itulah sebabnya POP3 cocok untuk satu perangkat dan IMAP untuk banyak perangkat.","2 waiting, 1 downloaded":"2 menunggu, 1 terunduh",Deleted:"Dihapus","At QUIT (UPDATE state)":"Saat QUIT (status UPDATE)","Best for":"Paling cocok untuk","A single device":"Satu perangkat","Bob’s mail app connects to pop.example.org on port 995, where TLS starts right away. Inside it, the server greets with +OK. (On port 110 the session starts in plain text and is upgraded with the STLS command.)":"Aplikasi email Bob terhubung ke pop.example.org di port 995, tempat TLS langsung dimulai. Di dalamnya, server menyapa dengan +OK. (Di port 110 sesi dimulai dalam teks biasa dan ditingkatkan dengan perintah STLS.)","USER, then PASS":"USER, lalu PASS","The app sends the user name with USER and the password with PASS. Each command gets its own +OK. Because the session is inside TLS, the password isn’t readable on the way.":"Aplikasi mengirim nama pengguna dengan USER dan kata sandi dengan PASS. Setiap perintah mendapat +OK sendiri. Karena sesinya berada di dalam TLS, kata sandi tidak bisa dibaca di perjalanan.","Protected by":"Dilindungi oleh","Check the Mailbox":"Periksa kotak surat","STAT and LIST":"STAT dan LIST","STAT returns the number of messages and their total size: 2 messages, 5120 bytes. LIST gives each message’s number and size, ending with a line holding just a dot.":"STAT mengembalikan jumlah pesan dan total ukurannya: 2 pesan, 5120 byte. LIST memberi nomor dan ukuran setiap pesan, diakhiri baris yang hanya berisi sebuah titik.","Message 1":"Pesan 1","Message 2":"Pesan 2",Download:"Unduh","RETR 1 asks for the first message. The server answers +OK with its size, then the message and a closing dot: 1904 bytes plus the reply line, two TCP segments.":"RETR 1 meminta pesan pertama. Server menjawab +OK beserta ukurannya, lalu pesannya dan sebuah titik penutup: 1904 byte ditambah baris balasan, dua segmen TCP.",Command:"Perintah","Delete & Quit":"Hapus & keluar","Deleted only at QUIT":"Baru dihapus saat QUIT","DELE 1 only marks the message. The server removes it when the app says QUIT: if the connection dropped before that, nothing would be deleted. Many apps offer “leave a copy on the server”, which skips DELE.":"DELE 1 hanya menandai pesan. Server menghapusnya ketika aplikasi mengucapkan QUIT: jika koneksi terputus sebelum itu, tidak ada yang terhapus. Banyak aplikasi menawarkan “tinggalkan salinan di server”, yang melewatkan DELE.","Marks message 1":"Menandai pesan 1",Removed:"Dihapus",Option:"Opsi","Leave a copy on server":"Tinggalkan salinan di server","PASS (password)":"PASS (kata sandi)","+OK 1904 octets, message, “.” (2 segments)":"+OK 1904 octets, pesan, “.” (2 segmen)","+OK 1904 octets, the 1,904-byte message, then a line holding only “.”":"+OK 1904 octets, pesan 1,904 byte, lalu baris yang hanya berisi “.”","Mail That Stays in Sync":"Email yang tetap sinkron","IMAP command":"Perintah IMAP","IMAP response":"Respons IMAP","Internet Message Access Protocol":"Protokol akses pesan internet","IMAP lets mail apps work with a mailbox that stays on the server. Folders, read and flagged marks and deletions are kept there, so a phone, a laptop and webmail all see the same mailbox. The server can also tell an app about new mail as it arrives.":"IMAP memungkinkan aplikasi email bekerja dengan kotak surat yang tetap berada di server. Folder, tanda sudah dibaca dan ditandai, serta penghapusan disimpan di sana, sehingga ponsel, laptop, dan webmail melihat kotak surat yang sama. Server juga bisa memberi tahu aplikasi tentang email baru saat email itu tiba.","Mail stays on the server":"Email tetap di server",Syncs:"Menyinkronkan","Folders and flags":"Folder dan flag","Mailbox in sync":"Kotak surat sinkron","Read once, read everywhere":"Dibaca sekali, terbaca di mana-mana","Bob’s app opened his inbox, read a message, which marked it \\Seen on the server for all his devices, and then waited with IDLE until the server announced new mail. Nothing was deleted: the server still holds everything.":"Aplikasi Bob membuka kotak masuknya dan membaca sebuah pesan, yang menandainya \\Seen di server untuk semua perangkatnya, lalu menunggu dengan IDLE sampai server mengumumkan email baru. Tidak ada yang dihapus: server masih menyimpan semuanya.","2, then 3 (new mail)":"2, lalu 3 (email baru)","Read mark":"Tanda sudah dibaca","\\Seen, stored on server":"\\Seen, disimpan di server","New mail":"Email baru","Pushed during IDLE":"Dikirim saat IDLE","Bob’s app connects to imap.example.org on port 993, where TLS starts right away. The server greets with an untagged “* OK” line that also lists its capabilities, such as IDLE.":"Aplikasi Bob terhubung ke imap.example.org di port 993, tempat TLS langsung dimulai. Server menyapa dengan baris “* OK” tanpa tag yang juga mendaftar kemampuannya, seperti IDLE.","Commands carry tags":"Perintah membawa tag","Every command starts with a tag the app chooses, like a1, and the server ends its answer with the same tag. That way several commands can be in flight and each reply is matched up. Lines starting with * are untagged data.":"Setiap perintah diawali tag pilihan aplikasi, seperti a1, dan server mengakhiri jawabannya dengan tag yang sama. Dengan begitu beberapa perintah bisa berjalan bersamaan dan setiap balasan cocok dengan perintahnya. Baris yang diawali * adalah data tanpa tag.",Tags:"Tag","Match replies to commands":"Mencocokkan balasan dengan perintah","Open the Inbox":"Buka kotak masuk","SELECT a folder":"SELECT sebuah folder","SELECT INBOX opens the folder. The server reports the message count, the flags it supports and the first unread message, then confirms the folder is open read-write.":"SELECT INBOX membuka folder. Server melaporkan jumlah pesan, flag yang didukungnya, dan pesan pertama yang belum dibaca, lalu mengonfirmasi bahwa folder terbuka untuk baca-tulis.","First unread":"Belum dibaca pertama",Access:"Akses","Read a Message":"Baca sebuah pesan","FETCH, and the \\Seen flag":"FETCH, dan flag \\Seen","FETCH 2 BODY[] downloads message 2 (three TCP segments). That sets its \\Seen flag on the server, so it shows as read on Bob’s phone too, and the message stays there.":"FETCH 2 BODY[] mengunduh pesan 2 (tiga segmen TCP). Itu memasang flag \\Seen-nya di server, sehingga pesan itu tampil sudah dibaca di ponsel Bob juga, dan pesannya tetap di sana.","Flag set":"Flag dipasang","\\Seen (on the server)":"\\Seen (di server)","Wait for New Mail":"Tunggu email baru","IDLE: the server pushes":"IDLE: server yang mengabari","IDLE tells the server “let me know when something changes”. About 42 seconds later Alice’s message arrives and the server pushes “* 3 EXISTS” straight away. The app ends IDLE with DONE and can fetch the new mail.":"IDLE memberi tahu server “kabari saya kalau ada yang berubah”. Sekitar 42 detik kemudian pesan Alice tiba dan server langsung mengirim “* 3 EXISTS”. Aplikasi mengakhiri IDLE dengan DONE dan bisa mengambil email baru itu.","Server says":"Kata server","* 3 EXISTS (new mail)":"* 3 EXISTS (email baru)","Ended by":"Diakhiri dengan","a1 LOGIN (user and password)":"a1 LOGIN (pengguna dan kata sandi)","* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, the 3,216-byte message, then a3 OK FETCH completed":"* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, pesan 3,216 byte, lalu a3 OK FETCH completed","Transferring Files":"Mentransfer file","FTP command":"Perintah FTP","FTP reply":"Balasan FTP","File data":"Data file","FTP moves files between a client and a server. It is unusual in using two TCP connections: one for commands and replies, and a fresh one for each file or listing. It dates from the early 1970s and sends everything, passwords included, as plain text.":"FTP memindahkan file antara klien dan server. Uniknya, FTP memakai dua koneksi TCP: satu untuk perintah dan balasan, dan satu koneksi baru untuk setiap file atau daftar isi. FTP berasal dari awal 1970-an dan mengirim semuanya, termasuk kata sandi, sebagai teks biasa.","21 control, data varies":"21 kontrol, data berubah-ubah",Connections:"Koneksi","Control + one per transfer":"Kontrol + satu per transfer",Encryption:"Enkripsi","None (plain text)":"Tidak ada (teks biasa)","Safer options":"Pilihan lebih aman","File downloaded":"File terunduh","Two connections, no encryption":"Dua koneksi, tanpa enkripsi","Commands went over the control connection, the file over its own data connection, and closing that connection marked the end of the file. Anyone on the path could have read the password and the file, which is why SFTP or FTPS is used today.":"Perintah lewat koneksi kontrol, file lewat koneksi datanya sendiri, dan penutupan koneksi itu menandai akhir file. Siapa pun di jalur bisa membaca kata sandi dan file-nya; itulah sebabnya kini orang memakai SFTP atau FTPS.","2 (control + data)":"2 (kontrol + data)",File:"File","4,000 bytes, 3 segments":"4,000 byte, 3 segmen",Password:"Kata sandi","Sent in plain text":"Dikirim sebagai teks biasa","Use instead":"Gunakan sebagai gantinya","Control Connection":"Koneksi kontrol","Port 21, plain text":"Port 21, teks biasa","The FTP app opens a TCP connection to ftp.example.com on port 21. This control connection carries commands and replies for the whole session. The server greets with 220. Like SMTP, every reply starts with a three-digit code.":"Aplikasi FTP membuka koneksi TCP ke ftp.example.com di port 21. Koneksi kontrol ini membawa perintah dan balasan untuk seluruh sesi. Server menyapa dengan 220. Seperti SMTP, setiap balasan diawali kode tiga digit.","USER and PASS, readable by anyone":"USER dan PASS, terbaca oleh siapa saja","The app sends USER, the server asks for the password with 331, and PASS sends it. Nothing is encrypted, so the user name and password cross every network on the way as readable text.":"Aplikasi mengirim USER, server meminta kata sandi dengan 331, dan PASS mengirimkannya. Tidak ada yang dienkripsi, jadi nama pengguna dan kata sandi melintasi setiap jaringan di jalur sebagai teks yang bisa dibaca.","Visible to":"Terlihat oleh","Anyone on the path":"Siapa pun di jalur","Passive Mode":"Mode pasif","The server names a data port":"Server menyebut port data","TYPE I asks for a byte-for-byte binary copy. PASV asks the server to open a port for the data connection. The reply encodes the address and port as six numbers: 195 × 256 + 149 = port 50069. The laptop connects out, which works through NAT.":"TYPE I meminta salinan biner byte demi byte. PASV meminta server membuka port untuk koneksi data. Balasannya mengodekan alamat dan port sebagai enam angka: 195 × 256 + 149 = port 50069. Laptop yang membuka koneksi keluar, dan itu bisa melewati NAT.","Data port":"Port data","Active mode":"Mode aktif","Server dials in: NAT blocks":"Server menghubungi balik: NAT memblokir","Data Connection":"Koneksi data","A second TCP connection":"Koneksi TCP kedua","The app opens a second TCP connection, to port 50069, and asks for the file on the control connection with RETR. The server answers 150 there and starts sending the file over the new connection.":"Aplikasi membuka koneksi TCP kedua, ke port 50069, dan meminta file di koneksi kontrol dengan RETR. Server menjawab 150 di sana dan mulai mengirim file lewat koneksi baru itu.","Data to":"Data ke","The File Arrives":"File tiba","Closing the connection ends it":"Menutup koneksi menandai akhirnya","The 4,000 bytes arrive in 3 TCP segments. FTP sends no length marker in the data itself: the server closes the data connection to mark the end of the file. Once the laptop has acknowledged everything, the server confirms with 226 on the control connection.":"Ke-4,000 byte itu tiba dalam 3 segmen TCP. FTP tidak mengirim penanda panjang di dalam datanya: server menutup koneksi data untuk menandai akhir file. Setelah laptop mengonfirmasi semuanya, server mengonfirmasi dengan 226 di koneksi kontrol.","End of file":"Akhir file","Data connection closed":"Koneksi data ditutup","4,000 bytes, readable by anyone":"4,000 byte, terbaca oleh siapa saja","end of file:":"akhir file:","data connection closed":"koneksi data ditutup",Quit:"Keluar","Close the control connection":"Tutup koneksi kontrol","QUIT ends the session and the server says goodbye with 221. For anything sensitive, SFTP (a different protocol, run over SSH) or FTPS (FTP inside TLS) gives the same job encryption.":"QUIT mengakhiri sesi dan server berpamitan dengan 221. Untuk apa pun yang sensitif, SFTP (protokol lain, berjalan di atas SSH) atau FTPS (FTP di dalam TLS) melakukan pekerjaan yang sama dengan enkripsi.","Encrypted cousins":"Kerabat terenkripsi","FTP data":"Data FTP","The file itself, unencrypted: anyone on the path could read it.":"File-nya sendiri, tanpa enkripsi: siapa pun di jalur bisa membacanya.","Secure Remote Login":"Login jarak jauh yang aman","Plain setup":"Penyiapan teks biasa","From laptop":"Dari laptop","From server":"Dari server","Some packets not shown":"Beberapa paket tidak ditampilkan","SSH gives you an encrypted, authenticated connection to another computer, to run commands on it, copy files (SFTP, scp) or carry other connections. The server proves who it is with a host key; you prove who you are with a key pair or a password.":"SSH memberi Anda koneksi terenkripsi dan terautentikasi ke komputer lain, untuk menjalankan perintah di sana, menyalin file (SFTP, scp), atau membawa koneksi lain. Server membuktikan siapa dirinya dengan host key; Anda membuktikan siapa diri Anda dengan pasangan kunci atau kata sandi.","Server proves":"Server membuktikan","Host key (known_hosts)":"Host key (known_hosts)","You prove":"Anda membuktikan","Key pair or password":"Pasangan kunci atau kata sandi","Logged in securely":"Login dengan aman","Encrypted from the key exchange on":"Terenkripsi sejak pertukaran kunci","The two sides agreed on algorithms, built shared keys with a post-quantum hybrid exchange, and the server proved its identity with its host key. Alice proved hers by signing with a private key that never left the laptop, then typed a command, one packet per key.":"Kedua pihak menyepakati algoritma, membangun kunci bersama dengan pertukaran hibrida pascakuantum, dan server membuktikan identitasnya dengan host key. Alice membuktikan identitasnya dengan menandatangani memakai kunci privat yang tidak pernah meninggalkan laptop, lalu mengetik sebuah perintah, satu paket per tombol.",Login:"Login","Ed25519 key, no password":"Kunci Ed25519, tanpa kata sandi","Say Hello":"Ucapkan halo","Versions, in plain text":"Versi, dalam teks biasa","Alice runs “ssh alice@server.example.com”. After the TCP handshake on port 22, each side sends one line of plain text naming the SSH protocol version (2.0) and its software. Everything else in SSH is binary.":"Alice menjalankan “ssh alice@server.example.com”. Setelah handshake TCP di port 22, setiap pihak mengirim satu baris teks biasa yang menyebut versi protokol SSH (2.0) dan perangkat lunaknya. Semua hal lain di SSH berbentuk biner.","Agree on Algorithms":"Sepakati algoritma","KEXINIT lists, first match wins":"Daftar KEXINIT, kecocokan pertama yang menang","Each side sends a KEXINIT listing every algorithm it supports, in order of preference, for key exchange, host keys, encryption, integrity and compression. In each category the first algorithm on the laptop’s list that the server also supports is chosen.":"Setiap pihak mengirim KEXINIT yang mendaftar semua algoritma yang didukungnya, urut menurut preferensi, untuk pertukaran kunci, host key, enkripsi, integritas, dan kompresi. Di setiap kategori, yang dipilih adalah algoritma pertama di daftar laptop yang juga didukung server.","Host key":"Host key","server’s algorithm lists":"daftar algoritma server","in order of preference":"urut menurut preferensi","laptop’s algorithm lists":"daftar algoritma laptop","Key Exchange":"Pertukaran kunci","Shared keys, and a host key check":"Kunci bersama, dan pemeriksaan host key","The laptop sends its half of a hybrid exchange: a Streamlined NTRU Prime key, chosen to resist future quantum computers, plus an X25519 key. The server answers with its half, its host key and a signature over the exchange. NEWKEYS switches encryption on.":"Laptop mengirim separuh bagiannya dari pertukaran hibrida: kunci Streamlined NTRU Prime, dipilih agar tahan terhadap komputer kuantum masa depan, ditambah kunci X25519. Server menjawab dengan separuh bagiannya, host key-nya, dan tanda tangan atas pertukaran itu. NEWKEYS menyalakan enkripsi.",Hybrid:"Hibrida","Matches known_hosts":"Cocok dengan known_hosts","First visit":"Kunjungan pertama","ssh asks you to confirm":"ssh meminta Anda mengonfirmasi","public keys":"kunci publik","its half, its host key":"separuh bagiannya, host key-nya","and a signature":"dan tanda tangan","Log In with a Key":"Login dengan kunci","Sign, don’t send a secret":"Tanda tangani, jangan kirim rahasia","The server lists the login methods it accepts. The laptop offers Alice’s public key, and the server says it would accept it. The laptop then signs this session with the private key, which never leaves the laptop. The server checks the signature against authorized_keys.":"Server mendaftar metode login yang diterimanya. Laptop menawarkan kunci publik Alice, dan server menjawab bahwa ia akan menerimanya. Lalu laptop menandatangani sesi ini dengan kunci privat, yang tidak pernah meninggalkan laptop. Server memeriksa tanda tangan itu dengan authorized_keys.",Methods:"Metode","Ed25519, private stays here":"Ed25519, kunci privat tetap di sini","Checked with":"Diperiksa dengan","alice’s public key":"kunci publik alice","would you accept it?":"apakah Anda menerimanya?","yes, that key":"ya, kunci itu","is in authorized_keys":"ada di authorized_keys","same key, plus a signature":"kunci yang sama, ditambah tanda tangan","made with the private key":"dibuat dengan kunci privat","logged in":"berhasil login","Open a Session":"Buka sesi","Channels inside one connection":"Kanal di dalam satu koneksi","One SSH connection can carry many channels: a shell, file transfers, forwarded ports. The laptop opens a session channel, then asks for a terminal and a shell (not shown), and the server sends its welcome text and a prompt.":"Satu koneksi SSH bisa membawa banyak kanal: shell, transfer file, port yang diteruskan. Laptop membuka kanal sesi, lalu meminta terminal dan shell (tidak ditampilkan), dan server mengirim teks sambutan serta prompt.",Channel:"Kanal",session:"sesi","Then asks for":"Lalu meminta","A terminal and a shell":"Terminal dan shell","Also possible":"Juga bisa","SFTP, port forwarding":"SFTP, penerusan port","open a channel:":"buka kanal:","channel open":"kanal terbuka","Type a Command":"Ketik perintah","Every key is a packet":"Setiap tombol adalah paket","Alice types pwd. Each key goes out at once in its own encrypted packet, and the server sends the character back to be shown (the echo). Since 9.5, OpenSSH sends keys on a 20 ms beat and adds decoy packets, so typing rhythm is harder to read from the timing.":"Alice mengetik pwd. Setiap tombol langsung dikirim dalam paket terenkripsinya sendiri, dan server mengirim balik karakternya untuk ditampilkan (echo). Sejak versi 9.5, OpenSSH mengirim tombol dengan ketukan 20 ms dan menambahkan paket umpan, agar ritme mengetik lebih sulit dibaca dari waktunya.","Per key":"Per tombol","1 packet, 90 bytes":"1 paket, 90 byte",Echo:"Echo","Sent back by the server":"Dikirim balik oleh server",Timing:"Waktu","20 ms beat plus decoys":"Ketukan 20 ms plus umpan","Enter key":"Tombol Enter","Client: KEX_ECDH_INIT (sntrup761x25519 public keys)":"Client: KEX_ECDH_INIT (kunci publik sntrup761x25519)","Server: KEX_ECDH_REPLY (host key, its half, signature)":"Server: KEX_ECDH_REPLY (host key, separuh bagiannya, tanda tangan)","Encrypted (len=44): service request, ssh-userauth":"Terenkripsi (len=44): permintaan layanan, ssh-userauth","Encrypted (len=44): service accept":"Terenkripsi (len=44): layanan diterima","Encrypted (len=68): login with method none":"Terenkripsi (len=68): login dengan metode none","Encrypted (len=52): try publickey,password":"Terenkripsi (len=52): coba publickey,password","Encrypted (len=140): offer public key":"Terenkripsi (len=140): menawarkan kunci publik","Encrypted (len=100): public key OK":"Terenkripsi (len=100): kunci publik OK","Encrypted (len=308): public key + signature":"Terenkripsi (len=308): kunci publik + tanda tangan","Encrypted (len=28): login success":"Terenkripsi (len=28): login berhasil","Encrypted (len=52): channel open: session":"Terenkripsi (len=52): buka kanal: session","Encrypted (len=44): channel open confirmed":"Terenkripsi (len=44): pembukaan kanal dikonfirmasi","Encrypted (len=36): keystroke":"Terenkripsi (len=36): ketukan tombol","Encrypted (len=36): echo":"Terenkripsi (len=36): echo","Encrypted (len=36): keystroke (Enter)":"Terenkripsi (len=36): ketukan tombol (Enter)","Encrypted (len=132): output and a new prompt":"Terenkripsi (len=132): output dan prompt baru","Packet length":"Panjang paket","Bytes after this field.":"Byte setelah kolom ini.","Padding length":"Panjang padding","Random padding brings the packet to a multiple of 8 bytes.":"Padding acak membuat paket menjadi kelipatan 8 byte.",Cookie:"Cookie","Host keys":"Host key","Ciphers, out":"Cipher, keluar","Ciphers, in":"Cipher, masuk","MACs, out":"MAC, keluar","Compression, out":"Kompresi, keluar","Compression, in":"Kompresi, masuk","Languages, out":"Bahasa, keluar","Languages, in":"Bahasa, masuk","First packet follows":"Paket pertama menyusul",Reserved:"Dicadangkan","Public keys":"Kunci publik","51 bytes: ssh-ed25519 public key":"51 byte: kunci publik ssh-ed25519","Server’s half":"Separuh milik server","1071 bytes (sntrup761 ciphertext 1,039 + X25519 32)":"1071 byte (ciphertext sntrup761 1,039 + X25519 32)",Signature:"Tanda tangan","83 bytes: ssh-ed25519 signature over the exchange":"83 byte: tanda tangan ssh-ed25519 atas pertukaran","From the next packet on, this side encrypts.":"Mulai paket berikutnya, pihak ini mengenkripsi.","SSH · encrypted packet":"SSH · paket terenkripsi","Encrypted packet":"Paket terenkripsi","With chacha20-poly1305 even the length is encrypted; a 16-byte tag at the end shows any change.":"Dengan chacha20-poly1305 bahkan panjangnya pun dienkripsi; tag 16 byte di akhir menunjukkan setiap perubahan.","SSH_MSG_USERAUTH_REQUEST (50): user “alice”, service “ssh-connection”, method “none”":"SSH_MSG_USERAUTH_REQUEST (50): pengguna “alice”, layanan “ssh-connection”, metode “none”","SSH_MSG_USERAUTH_FAILURE (51): methods that can continue: “publickey,password”":"SSH_MSG_USERAUTH_FAILURE (51): metode yang bisa dilanjutkan: “publickey,password”","SSH_MSG_USERAUTH_REQUEST (50): method “publickey”, no signature, the ssh-ed25519 public key":"SSH_MSG_USERAUTH_REQUEST (50): metode “publickey”, tanpa tanda tangan, kunci publik ssh-ed25519","SSH_MSG_USERAUTH_PK_OK (60): the same ssh-ed25519 key":"SSH_MSG_USERAUTH_PK_OK (60): kunci ssh-ed25519 yang sama","SSH_MSG_USERAUTH_REQUEST (50): method “publickey-hostbound-v00@openssh.com”, the key, the server’s host key and a signature":"SSH_MSG_USERAUTH_REQUEST (50): metode “publickey-hostbound-v00@openssh.com”, kuncinya, host key server, dan tanda tangan","SSH_MSG_CHANNEL_OPEN (90): “session”, channel 0, window 2 MB, packets up to 32 KB":"SSH_MSG_CHANNEL_OPEN (90): “session”, kanal 0, window 2 MB, paket hingga 32 KB","SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): channel 0 is open":"SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): kanal 0 terbuka","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 byte, “p”","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 byte, “p”, dikirim balik untuk ditampilkan","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 byte, “w”","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 byte, “w”, dikirim balik untuk ditampilkan","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 byte, “d”","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 byte, “d”, dikirim balik untuk ditampilkan","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, a carriage return (Enter)":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 byte, carriage return (Enter)","SSH_MSG_CHANNEL_DATA (94), channel 0: 94 bytes: a new line, the shell’s terminal codes, “/home/alice”, and the coloured prompt":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 94 byte: baris baru, kode terminal shell, “/home/alice”, dan prompt berwarna","Encryption Explained":"Enkripsi dijelaskan","From browser":"Dari browser","TLS puts a secure channel on top of TCP. It proves the server’s identity with a certificate, agrees on fresh keys, then encrypts and authenticates everything sent. HTTPS, secure email and many other protocols run inside it. SSL was the name of its predecessor.":"TLS memasang kanal aman di atas TCP. TLS membuktikan identitas server dengan sertifikat, menyepakati kunci baru, lalu mengenkripsi dan mengautentikasi semua yang dikirim. HTTPS, email aman, dan banyak protokol lain berjalan di dalamnya. SSL adalah nama pendahulunya.",Sits:"Letaknya","Between TCP and the app":"Di antara TCP dan aplikasi","OSI layer":"Lapisan OSI","Often placed at 6":"Sering ditaruh di 6",Current:"Saat ini",Retired:"Sudah pensiun","SSL 2 and 3, TLS 1.0 and 1.1":"SSL 2 dan 3, TLS 1.0 dan 1.1","The app’s own (443, 993 …)":"Port aplikasinya sendiri (443, 993 …)","Secure from start to finish":"Aman dari awal sampai akhir","One round trip to set up":"Satu kali pulang-pergi untuk penyiapan","One round trip agreed on a version, a cipher and a post-quantum hybrid key. The certificate chain proved who the server was, and every byte after the Server Hello was encrypted and authenticated, right up to the close_notify. Press REPLAY to watch it again.":"Satu kali pulang-pergi cukup untuk menyepakati versi, cipher, dan kunci hibrida pascakuantum. Rantai sertifikat membuktikan siapa server itu, dan setiap byte setelah Server Hello dienkripsi dan diautentikasi, sampai close_notify. Tekan ULANGI untuk menontonnya lagi.","1 round trip":"1 kali pulang-pergi","Everything the browser supports":"Semua yang didukung browser","After the TCP handshake the browser lists what it can do: TLS versions, cipher suites, and key shares for the groups it expects, including the post-quantum hybrid X25519MLKEM768. It also names the site (SNI) and the protocols it speaks (ALPN).":"Setelah handshake TCP, browser mendaftar apa yang bisa dilakukannya: versi TLS, cipher suite, dan key share untuk grup yang diharapkannya, termasuk hibrida pascakuantum X25519MLKEM768. Browser juga menyebut situsnya (SNI) dan protokol yang dipakainya (ALPN).",Versions:"Versi","versions, ciphers, key shares":"versi, cipher, key share","Choices made, keys computed":"Pilihan dibuat, kunci dihitung","The server picks TLS 1.3, the cipher suite and the hybrid group, and sends its own key share. From the two shares both sides compute the same secret without it ever crossing the network. Everything after this message is encrypted.":"Server memilih TLS 1.3, cipher suite, dan grup hibrida, lalu mengirim key share-nya sendiri. Dari kedua share itu, kedua pihak menghitung rahasia yang sama tanpa rahasia itu pernah melintasi jaringan. Semua setelah pesan ini terenkripsi.",Group:"Grup","From here on":"Mulai dari sini","its key share":"key share-nya",Certificate:"Sertifikat","Who the server is, proven":"Siapa server itu, terbukti","Now encrypted, the flight continues: the chosen protocol (http/1.1), the certificate chain, a signature made with the certificate’s private key, and Finished.":"Kini terenkripsi, kirimannya berlanjut: protokol yang dipilih (http/1.1), rantai sertifikat, tanda tangan yang dibuat dengan kunci privat sertifikat, dan Finished.",Chain:"Rantai","Site → intermediate → root":"Situs → perantara → root","Proves the private key":"Membuktikan kunci privat",Checked:"Diperiksa","Name, dates, trusted root":"Nama, tanggal, root tepercaya","encrypted: http/1.1, certificates,":"terenkripsi: http/1.1, sertifikat,","signature, Finished":"tanda tangan, Finished","One round trip, then data":"Satu kali pulang-pergi, lalu data","The browser sends its own Finished: a check value over everything both sides said, keyed with the new secret, so any tampering with the hellos would show. TLS 1.3 needs one round trip before data flows; TLS 1.2 needed two.":"Browser mengirim Finished-nya sendiri: nilai pemeriksa atas semua yang dikatakan kedua pihak, dihitung dengan rahasia baru, sehingga setiap utak-atik pada hello akan ketahuan. TLS 1.3 butuh satu kali pulang-pergi sebelum data mengalir; TLS 1.2 butuh dua.",Covers:"Mencakup","The whole handshake":"Seluruh handshake","For old middleboxes":"Untuk middlebox lama","check value over":"nilai pemeriksa atas","the whole handshake":"seluruh handshake","Encrypted Data":"Data terenkripsi","Records, tags and tickets":"Record, tag, dan tiket","HTTP now travels in encrypted records, each with a 16-byte tag that exposes any change. The server also sends two session tickets: next time the browser can resume with one and skip the certificate.":"HTTP kini berjalan dalam record terenkripsi, masing-masing dengan tag 16 byte yang membongkar setiap perubahan. Server juga mengirim dua tiket sesi: lain kali browser bisa melanjutkan dengan salah satunya dan melewati sertifikat.","Per record":"Per record","22 bytes of overhead":"22 byte overhead","2, for resuming later":"2, untuk melanjutkan nanti",Visible:"Terlihat","IPs, SNI, sizes, timing":"IP, SNI, ukuran, waktu","2 session tickets":"2 tiket sesi","for resuming later":"untuk melanjutkan nanti",Closing:"Penutupan","close_notify, then TCP":"close_notify, lalu TCP","After 75 idle seconds the server closes the connection. It first sends a close_notify alert, encrypted like everything else, so the browser knows the data ended on purpose and wasn’t cut short by an attacker. Then TCP closes as usual.":"Setelah 75 detik tanpa aktivitas, server menutup koneksi. Server lebih dulu mengirim alert close_notify, terenkripsi seperti semua yang lain, agar browser tahu bahwa data berakhir dengan sengaja dan tidak dipotong oleh penyerang. Lalu TCP ditutup seperti biasa.",Alert:"Alert","Shows nothing was cut off":"Menunjukkan tidak ada yang terpotong","TCP FIN from both sides":"TCP FIN dari kedua pihak","alert: close_notify":"alert: close_notify",encrypted:"terenkripsi","Server Hello, Change Cipher Spec (+ encrypted)":"Server Hello, Change Cipher Spec (+ terenkripsi)","Encrypted handshake (continued)":"Handshake terenkripsi (lanjutan)","Encrypted handshake (certificate, verify, Finished)":"Handshake terenkripsi (sertifikat, verifikasi, Finished)","Application Data (inside: close_notify alert)":"Application Data (di dalamnya: alert close_notify)","Alert: close_notify (the data ends here, on purpose)":"Alert: close_notify (data berakhir di sini, dengan sengaja)","No IP address":"Tanpa alamat IP","192.168.1.1 · DHCP server":"192.168.1.1 · server DHCP"},o={strings:{...i,...t},patterns:[[/^([\d,]+) bytes$/,"$1 byte"],[/^(Ethernet II|IPv4|UDP|TCP) · (\d+) bytes$/,"$1 · $2 byte"],[/^(Application Data|Handshake|Change Cipher Spec), ([\d,]+) bytes?$/,"$1, $2 byte"],[/^([\d,]+) bytes: report\.pdf, bytes (.+)$/,"$1 byte: report.pdf, byte $2"],[/^(.+) h later$/,"$1 jam kemudian"],[/^(.+) min later$/,"$1 menit kemudian"],[/^(.+) s later$/,"$1 detik kemudian"],[/^(\S+) \(relative\)$/,"$1 (relatif)"],[/^(\d+) \(ephemeral\)$/,"$1 (efemeral)"],[/^(\d+) TCP segments$/,"$1 segmen TCP"],[/^(\d+) segments$/,"$1 segmen"],[/^(.*), (\d+) segments$/,"$1, $2 segmen"],[/^TLS 1\.3 · (\d+) records? · bytes (.+) of (.+)$/,"TLS 1.3 · $1 record · byte $2 dari $3"],[/^TLS 1\.3 · (\d+) records?$/,"TLS 1.3 · $1 record"],[/^Ethernet padding · (\d+) bytes$/,"Padding Ethernet · $1 byte"],[/^(\d+) zero bytes, up to the 300-byte minimum$/,"$1 byte nol, hingga batas minimum 300 byte"],[/^(\d+) zero bytes$/,"$1 byte nol"],[/^(\d+) random bytes$/,"$1 byte acak"],[/^Seen as it leaves (.+)$/,"Terlihat saat keluar dari $1"],[/^Option (\d+)$/,"Opsi $1"],[/^value (\d+), echo (\d+)$/,"nilai $1, echo $2"],[/^20 bytes, plus (\d+) of options\.$/,"20 byte, ditambah $1 byte opsi."],[/^Windows starts at (\d+)\. Set to (\d+) on purpose here\.$/,"Windows mulai dari $1. Di sini sengaja diatur ke $2."],[/^Started at (\d+); (\d+) routers? on the way each took 1\.$/,(r,e,a)=>a==="1"?`Dimulai dari ${e}; router di jalur menguranginya 1.`:`Dimulai dari ${e}; masing-masing dari ${a} router di jalur menguranginya 1.`],[/^all (\d+) bytes of it$/,"seluruh $1 byte-nya"],[/^The packet that caused this, as the reporting device received it \(TTL (\d+)\), so the sender can tell which packet it was\.$/,"Paket penyebabnya, seperti yang diterima perangkat pelapor (TTL $1), agar pengirim tahu paket mana itu."],[/^Port (\d+), TLS from the start$/,"Port $1, TLS sejak awal"],[/^(\d+), TLS from the start$/,"$1, TLS sejak awal"]],post:n};export{o as default};
